const h=e=>{const t=e.s.members.find(n=>n.kind==="column"&&n.n2==="B"),a=t?e.sol.memberMap[t.id]:void 0;return a?a.stations[a.stations.length-1].M:0},l=e=>e.sol.ok?Math.max(0,...e.sol.members.filter(t=>t.id!=="tie").map(t=>Math.max(Math.abs(t.maxM.value),Math.abs(t.minM.value)))):0,d=e=>{const t=Number(e.L),a=Math.round(Number(e.n)),n=Number(e.P);let s=0;for(let i=1;i<a;i++){const $=i*t/a;let o=0;for(let m=1;m<a;m++){const r=m*t/a;o+=r<=$?n*r*(t-$)/t:n*$*(t-r)/t}s=Math.max(s,o)}return s},c=[{id:"l.rc-sys-indet.fixed",xp:30,title:{en:"Fix the column bases: the knees take more, the span less — and the footings get a moment",ar:"ثبّت ركائز الأعمدة: الأركان بتاخد أكتر والبحر أقل — والقواعد بياخدوا عزم"},check:e=>e.template==="hall"&&e.params.bases==="fixed"&&e.sol.ok},{id:"l.rc-sys-indet.taper",xp:30,title:{en:"Model the real taper of the columns and compare it with the 5/6·t rule in the hand method",ar:"مثّل تدريج الأعمدة الحقيقي وقارنه بقاعدة 5/6·t في الحل اليدوي"},check:e=>e.template==="hall"&&e.params.col==="taper"&&e.tab==="hand"},{id:"l.rc-sys-indet.sky",xp:30,title:{en:"Open a sky-light over the middle third: a softer beam sends more moment to the knees",ar:"افتح شخشيخة في التلت الأوسط: الكمرة الأطرى بتبعت عزم أكتر للأركان"},check:e=>e.template==="hall"&&e.params.slab==="sky"&&e.sol.ok}],f=[{id:"l.rc-sys-indet.reverse",xp:40,title:{en:"Let the cantilever win: reverse the column-top moment (tension on the inner face)",ar:"خلّي الكابولي يكسب: اعكس عزم راس العمود (الشد على الوش الداخلي)"},hint:{en:"Lighten the span (P, w_g) or lengthen and load the cantilever.",ar:"خفّف البحر (P و w_g) أو طوّل الكابولي وحمّله."},check:e=>e.template==="hall"&&Number(e.params.c)>0&&h(e)>1},{id:"l.rc-sys-indet.balance",xp:50,title:{en:"Balance the knee: bring the column-top moment below 30 kN·m with a loaded cantilever",ar:"وازن الركن: نزّل عزم راس العمود تحت 30 kN·m بكابولي محمّل"},check:e=>e.template==="hall"&&Number(e.params.c)>0&&Number(e.params.wc)>0&&e.sol.ok&&Math.abs(h(e))<30}],k=[{id:"l.rc-sys-indet.rise",xp:30,title:{en:"Double the rise (f ≥ 4 m) and read the smaller thrust in the hand method",ar:"ضاعف ارتفاع الجمالون (f ≥ 4 م) واقرا الدفع الأصغر في الحل اليدوي"},check:e=>e.template==="hallgable"&&e.params.type==="2h"&&Number(e.params.f)>=4&&e.tab==="hand"},{id:"l.rc-sys-indet.h3",xp:40,title:{en:"Fix the bases and compare the H/3 hinge approximation with the exact frame",ar:"ثبّت الركائز وقارن تقريب مفصلة H/3 بالإطار المضبوط"},check:e=>e.template==="hallgable"&&e.params.type==="fixed"&&e.tab==="hand"},{id:"l.rc-sys-indet.tie",xp:40,title:{en:"Tie the knees: the supports no longer feel any thrust",ar:"اربط الأركان بشداد: الركائز مابقتش تحس بأي دفع أفقي"},check:e=>{var t;return e.template==="hallgable"&&e.params.type==="tie"&&e.sol.ok&&Math.abs(((t=e.sol.reactions.A)==null?void 0:t[0])??1)<.5}}],_=[{id:"l.rc-sys-indet.rigid",xp:30,title:{en:"Neglect the tie extension: the tie force comes close to M₀/h",ar:"اهمل استطالة الشداد: قوته بتقرب من M₀/h"},check:e=>e.template==="polygon"&&e.params.tie==="rigid"&&e.params.load==="all"&&e.sol.ok},{id:"l.rc-sys-indet.bench",xp:50,title:{en:"Give the stretching tie enough steel to bring the frame moment down to the 5% benchmark",ar:"ادّي الشداد اللي بيستطيل حديد كفاية لحد ما عزم الإطار ينزل لحد الـ 5%"},check:e=>e.template==="polygon"&&e.params.tie==="rc"&&e.params.load==="all"&&e.sol.ok&&l(e)<=.055*d(e.params)},{id:"l.rc-sys-indet.half",xp:30,title:{en:"Load only the left half: the polygon leaves the thrust line and bends",ar:"حمّل النص الشمال بس: المضلع بيبعد عن خط الضغط وبينحني"},check:e=>e.template==="polygon"&&e.params.load==="half"&&e.sol.ok&&l(e)>.15*d(e.params)}],b={sections:[{id:"methods",title:{en:"Which method for which hall",ar:"أنهي طريقة لأنهي صالة"},blocks:[{t:"p",text:{en:"A hall frame covers 12–25 m with one beam and two columns cast together. Two hinges already make it indeterminate to the first degree; fixed bases make it three times indeterminate (twice, once symmetry is used). These frames are solved by three routes, chosen by the shape of the frame and of the load:",ar:"إطار الصالة بيغطي 12–25 م بكمرة وعمودين مصبوبين مع بعض. المفصلتين لوحدهم بيخلّوه غير محدد من الدرجة الأولى؛ والركائز الثابتة بتخليه غير محدد تلات مرات (مرتين بعد ما نستغل التماثل). والإطارات دي بتتحل بتلات طرق، وبنختار حسب شكل الإطار وشكل الحمل:"}},{t:"table",head:[{en:"Method",ar:"الطريقة"},{en:"Use it when",ar:"استخدمها لما"},{en:"What it gives",ar:"بتديك إيه"}],rows:[[{en:"Moment distribution",ar:"توزيع العزوم (هاردي كروس)"},{en:"the frame and its load are symmetric and the knees do not sway: two-hinged and fixed halls under gravity",ar:"الإطار وحمله متماثلين والأركان مابتتحركش جنب: صالات بمفصلين أو ثابتة تحت الأحمال الرأسية"},{en:"the knee moment in one balance",ar:"عزم الركن في توازن واحد"}],[{en:"Virtual work",ar:"الشغل الافتراضي"},{en:"the knees move, or a link member is present: gable frames, roller–fixed frames, frames with a strut or a tie",ar:"الأركان بتتحرك، أو فيه وصلة: الإطارات الجمالونية، وإطار على ركيزة متحركة وثابتة، والإطارات بدعامة ضغط أو شداد"},{en:"the redundant X from δ₁₀ + X·δ₁₁ = 0",ar:"المجهول الزائد X من δ₁₀ + X·δ₁₁ = 0"}],[{en:"Approximate method",ar:"الحل التقريبي"},{en:"polygon frames, arch girders, arch slabs — or a quick check of any frame",ar:"الإطارات المضلعة والكمرات المقوّسة والبلاطات المقوّسة — أو مراجعة سريعة لأي إطار"},{en:"the tie force M₀/h, moments from assumed hinges",ar:"قوة الشداد M₀/h، وعزوم من مفصلات مفروضة"}]]},{t:"note",tone:"tip",text:{en:"In the first two methods only the ratios of the inertias matter: write every inertia as a multiple of the column's I_c and E cancels out.",ar:"في أول طريقتين النِّسَب بين عزوم القصور بس هي اللي بتفرق: اكتب كل عزم قصور كمضاعف لـ I_c بتاع العمود، و E بتختصر."}},{t:"quiz",q:{kind:"mcq",q:{en:"A two-hinged gable frame carries snow on both slopes. The shortest route to its moments is…",ar:"إطار جمالوني ذو مفصلين شايل تلج على الميلين. أقصر طريق لعزومه…"},options:[{en:"moment distribution in one balance",ar:"توزيع العزوم في توازن واحد"},{en:"virtual work with the horizontal thrust as X",ar:"الشغل الافتراضي والدفع الأفقي هو X"},{en:"the approximate tie rule M₀/h",ar:"قاعدة الشداد التقريبية M₀/h"}],answer:1,explain:{en:"Under a symmetric load the ridge drops and the knees spread outwards — joint translations that would cost the distribution extra sway steps. With one redundant, virtual work is short.",ar:"تحت الحمل المتماثل التاج بينزل والأركان بتفتح لبره — حركات للعقد هتكلّف التوزيع خطوات زيادة. ومع مجهول زائد واحد، الشغل الافتراضي قصير."}}}]},{id:"columns",title:{en:"Column inertia: the 5/6·t rule",ar:"عزم قصور العمود: قاعدة 5/6·t"},blocks:[{t:"p",text:{en:"The column of a two-hinged frame has no moment at its hinge and its largest moment at the knee, so it is tapered: depth $t$ at the knee, about $t/2$ at the hinge. The distribution needs one stiffness for it, so the taper is replaced by a prism of depth $\\tfrac{5}{6}t$ — simply the depth of the taper read $2h/3$ above the hinge: $t/2 + \\tfrac23\\cdot t/2 = \\tfrac56 t$. A fixed-base column is **prismatic**, $(1.0 \\to 1.2)\\,t$ deep over its whole height from the knee to the footing ($t$ = the depth of the beam), and keeps its full depth:",ar:"عمود الإطار ذو المفصلين مفيهوش عزم عند مفصلته وأكبر عزم عند الركن، علشان كده بيتعمل متدرّج: عمقه $t$ عند الركن وحوالي $t/2$ عند المفصلة. التوزيع محتاج جساءة واحدة ليه، فبنبدّل التدريج بمنشور عمقه $\\tfrac{5}{6}t$ — وده ببساطة عمق التدريج على ارتفاع $2h/3$ فوق المفصلة: $t/2 + \\tfrac23\\cdot t/2 = \\tfrac56 t$. والعمود ثابت الركيزة **منشوري**، عمقه $(1.0 \\to 1.2)\\,t$ على طوله كله من الركن للقاعدة ($t$ = عمق الكمرة)، وبياخد عمقه كامل:"}},{t:"eq",tex:["I_c = \\dfrac{b\\,\\left(\\tfrac{5}{6}\\,t\\right)^3}{12}","I_c = \\dfrac{b\\,t_c^3}{12},\\qquad t_c = (1.0 \\to 1.2)\\,t"],caption:{en:"First line: two-hinged frame, column tapered from t at the knee to about t/2 at the hinge. Second line: fixed base — a prismatic column of depth t_c from knee to footing.",ar:"السطر الأول: إطار ذو مفصلين، العمود متدرّج من t عند الركن لحوالي t/2 عند المفصلة. السطر التاني: ركيزة ثابتة — عمود منشوري عمقه t_c من الركن للقاعدة."}},{t:"p",text:{en:"Where does 5/6 come from? A prism has the same knee stiffness (far end hinged) as a linear taper from $t/2$ to $t$ when its depth is $0.85t$; the rule rounds it to $\\tfrac{5}{6}t = 0.83t$, a little softer. **Example:** a 400 × 1200 column tapered to 600 at its hinge: $I_c = 0.4\\times(\\tfrac{5}{6}\\times1.2)^3/12 = 0.4\\times1.0^3/12 = 0.0333$ m⁴ — exactly the inertia of a straight 400 × 1000 column. The lab can build the real taper in six steps: for the hall of this lesson it gives a knee moment 0.8% above the 5/6·t prism.",ar:"الـ 5/6 جاية منين؟ المنشور بيدّي نفس جساءة الركن (والطرف التاني مفصلي) زي التدريج الخطي من $t/2$ لـ $t$ لما عمقه يبقى $0.85t$؛ والقاعدة بتقرّبها لـ $\\tfrac{5}{6}t = 0.83t$، أطرى سنة. **مثال:** عمود 400 × 1200 متدرّج لـ 600 عند مفصلته: $I_c = 0.4\\times(\\tfrac{5}{6}\\times1.2)^3/12 = 0.4\\times1.0^3/12 = 0.0333$ م⁴ — بالظبط عزم قصور عمود مستقيم 400 × 1000. والمعمل يقدر يبني التدريج الحقيقي على ست درجات: في صالة الدرس ده بيدّي عزم ركن أعلى من منشور 5/6·t بـ 0.8%."}},{t:"p",text:{en:"**Axes and the height h.** The statical axis of a tapered column is a straight line $t/4$ from its **outer** face: at the hinge the section is $t/4 + t/4$ about it, at the knee $t/4$ outside and $3t/4$ inside. A prismatic beam has its axis at mid-depth. The height $h$ used in the stiffness runs from the hinge (or the top of a fixed footing) up to the **beam axis**. **Example:** roof slab at +7.00, hinges 1.25 m below the ground, beam 1.50 m deep: $h = 7.00 + 1.25 - 0.75 = 7.50$ m — the hall of this lesson.",ar:"**المحاور والارتفاع h.** المحور الإنشائي للعمود المتدرّج خط مستقيم على بعد $t/4$ من وشه **الخارجي**: عند المفصلة القطاع $t/4 + t/4$ حواليه، وعند الركن $t/4$ بره و $3t/4$ جوه. والكمرة المنشورية محورها في نص عمقها. والارتفاع $h$ اللي بندخل بيه في الجساءة من المفصلة (أو وش القاعدة الثابتة) لحد **محور الكمرة**. **مثال:** بلاطة السقف عند +7.00، والمفصلات تحت الأرض بـ 1.25 م، والكمرة عمقها 1.50 م: $h = 7.00 + 1.25 - 0.75 = 7.50$ م — صالة الدرس ده."}},{t:"quiz",q:{kind:"num",q:{en:"Two-hinged frame, column 350 × 1080 at the knee, tapered to its hinge. I_c (m⁴)?",ar:"إطار ذو مفصلين، العمود 350 × 1080 عند الركن ومتدرّج لحد مفصلته. I_c (م⁴)؟"},answer:.021263,tol:.005,unit:"m⁴",explain:{en:"$\\tfrac{5}{6}\\times1.08 = 0.90$ m, $I_c = 0.35\\times0.90^3/12 = 0.0213$ m⁴.",ar:"$\\tfrac{5}{6}\\times1.08 = 0.90$ م، و $I_c = 0.35\\times0.90^3/12 = 0.0213$ م⁴."}}}]},{id:"beams",title:{en:"Beam inertia: the T-section and the μ table",ar:"عزم قصور الكمرة: القطاع T وجدول μ"},blocks:[{t:"p",text:{en:"The roof slab is cast with the frame beam, so the beam works as a T-section. Its flange: $B = 6t_s + b_0$ under a solid slab, $B = b_0 + 2x$ under hollow blocks ($x$ = the solid strip left beside the beam). With $\\alpha = t_s/t$ and $\\beta = b_0/B$ a factor $\\mu$ is read from a table:",ar:"بلاطة السقف مصبوبة مع كمرة الإطار، فالكمرة بتشتغل قطاع T. الشفة بتاعتها: $B = 6t_s + b_0$ تحت بلاطة مصمتة، و $B = b_0 + 2x$ تحت الهوردي ($x$ = الشريحة المصمتة اللي بتتساب جنب الكمرة). وبـ $\\alpha = t_s/t$ و $\\beta = b_0/B$ بنقرا معامل $\\mu$ من جدول:"}},{t:"eq",tex:["B = 6\\,t_s + b_0,\\qquad B = b_0 + 2x","I_b = \\mu\\cdot10^{-4}\\,B\\,t^3,\\qquad \\mu = f\\left(\\dfrac{t_s}{t},\\ \\dfrac{b_0}{B}\\right)"]},{t:"table",head:["α = t_s/t ＼ β = b₀/B","0.20","0.25","0.30","0.35","0.40","0.50"],rows:[["0.06","252","293","332","369","406","479"],["0.08","270","311","350","388","424","495"],["0.10","283","326","366","403","439","509"],["0.12","293","338","378","416","452","521"],["0.15","304","351","392","431","468","536"],["0.20","314","363","407","448","485","553"]],caption:{en:"μ = 10⁴·I/(B·t³) of the gross T-section; interpolate linearly. A rectangle (β = 1) gives 833.",ar:"μ = 10⁴·I/(B·t³) للقطاع T الكامل؛ استكمل خطياً. والمستطيل (β = 1) بيدّي 833."}},{t:"p",text:{en:"The table is just the T-section worked out once — area, centroid from the top, and the inertia of flange and web about it:",ar:"الجدول ده هو القطاع T محسوب مرة واحدة وخلاص — المساحة ومركز الثقل من فوق وعزم قصور الشفة والعصب حواليه:"}},{t:"eq",tex:["A = B\\,t_s + b_0(t - t_s),\\qquad \\bar{y} = \\dfrac{B t_s\\,\\tfrac{t_s}{2} + b_0(t - t_s)\\left(t_s + \\tfrac{t - t_s}{2}\\right)}{A}","I = \\dfrac{B t_s^3}{12} + B t_s\\left(\\bar{y} - \\tfrac{t_s}{2}\\right)^2 + \\dfrac{b_0(t - t_s)^3}{12} + b_0(t - t_s)\\left(t_s + \\tfrac{t - t_s}{2} - \\bar{y}\\right)^2"]},{t:"p",text:{en:"**Example:** a 400 × 1500 beam under a 120 mm slab: $B = 6\\times0.12 + 0.40 = 1.12$ m, $\\alpha = 0.08$, $\\beta = 0.357$ → $\\mu = 388 + 0.14\\times36 = 393$ → $I_b = 393\\times10^{-4}\\times1.12\\times1.5^3 = 0.1486$ m⁴ — 4.457 times the 0.0333 m⁴ of the column. Two sections along one beam are averaged by length: a 6 m sky-light over the middle of this 20 m beam removes the slab there, $I_{b2} = 0.4\\times1.5^3/12 = 0.1125$ m⁴ and $I_b = (0.1486\\times14 + 0.1125\\times6)/20 = 0.1377$ m⁴. A beam without any slab is simply $bt^3/12$.",ar:"**مثال:** كمرة 400 × 1500 تحت بلاطة 120 مم: $B = 6\\times0.12 + 0.40 = 1.12$ م، و $\\alpha = 0.08$، و $\\beta = 0.357$ ← $\\mu = 388 + 0.14\\times36 = 393$ ← $I_b = 393\\times10^{-4}\\times1.12\\times1.5^3 = 0.1486$ م⁴ — 4.457 مرة الـ 0.0333 م⁴ بتوع العمود. ولو الكمرة ليها قطاعين على طولها بناخد المتوسط بالطول: شخشيخة 6 م في نص الكمرة 20 م بتشيل البلاطة هناك، $I_{b2} = 0.4\\times1.5^3/12 = 0.1125$ م⁴ و $I_b = (0.1486\\times14 + 0.1125\\times6)/20 = 0.1377$ م⁴. والكمرة اللي مفيش عليها بلاطة خالص $bt^3/12$ وبس."}},{t:"eq",tex:"I_b = \\dfrac{I_{b1}\\cdot 2L_1 + I_{b2}\\cdot L_2}{2L_1 + L_2}",caption:{en:"2L₁ = the two slab zones, L₂ = the sky-light zone.",ar:"2L₁ = منطقتين البلاطة، و L₂ = منطقة الشخشيخة."}},{t:"steps",items:[{en:"**Under hollow blocks** the flange is the solid strip beside the beam, $B = b_0 + 2x$, and its depth $t_s$ is the **whole slab depth** (blocks plus topping), since that strip is solid concrete: a 300 mm beam with 100 mm solid strips under a 250 mm hollow-block slab has $B = 0.50$ m and $t_s = 0.25$ m.",ar:"**تحت الهوردي** الشفة هي الشريحة المصمتة جنب الكمرة، $B = b_0 + 2x$، وعمقها $t_s$ هو **تخانة البلاطة كلها** (البلوك والبلاطة العلوية)، لأن الشريحة دي خرسانة مصمتة: كمرة 300 مم بشرايح مصمتة 100 مم تحت هوردي 250 مم ليها $B = 0.50$ م و $t_s = 0.25$ م."},{en:"**An edge frame** — the slab on one side only, an L-section — is taken, for simplicity, as the rectangle $b\\,t^3/12$: an edge frame of the 20 m hall has $I_b = 0.4\\times1.5^3/12 = 0.1125$ m⁴.",ar:"**إطار الطرف** — البلاطة من ناحية واحدة بس، قطاع L — بناخده للتسهيل مستطيل $b\\,t^3/12$: إطار الطرف في صالة الـ 20 م ليه $I_b = 0.4\\times1.5^3/12 = 0.1125$ م⁴."},{en:"**Under a sky-light** the beam has no flange: average the inertia by length as above, and design the mid-span section there as a rectangle.",ar:"**تحت الشخشيخة** الكمرة مالهاش شفة: خد متوسط عزم القصور بالطول زي اللي فوق، وصمّم قطاع نص البحر هناك كمستطيل."}]},{t:"quiz",q:{kind:"num",q:{en:"A beam: I_b1 = 0.12 m⁴ over 12 m with slab, I_b2 = 0.08 m⁴ over a 6 m sky-light. Averaged I_b (m⁴)?",ar:"كمرة: I_b1 = 0.12 م⁴ على 12 م ببلاطة، و I_b2 = 0.08 م⁴ على 6 م شخشيخة. متوسط I_b (م⁴)؟"},answer:.10667,tol:.005,unit:"m⁴",explain:{en:"$(0.12\\times12 + 0.08\\times6)/18 = 1.92/18 = 0.1067$ m⁴.",ar:"$(0.12\\times12 + 0.08\\times6)/18 = 1.92/18 = 0.1067$ م⁴."}}}]},{id:"stiffness",title:{en:"Stiffness and distribution factors",ar:"الجساءة ومعاملات التوزيع"},blocks:[{t:"p",text:{en:"At the knee the beam and the column share any unbalanced moment in proportion to their stiffness $K$. The far end sets the factor: $I/L$ when it is fixed, $\\tfrac34 I/L$ when it is hinged — and $\\tfrac12 I/L$ for the beam of a symmetric frame under a symmetric load, because its two ends turn by equal and opposite angles (the frame is cut at its axis of symmetry: $2EI/L$ instead of $4EI/L$).",ar:"عند الركن الكمرة والعمود بيقسموا أي عزم مش متزن بنسبة جساءتهم $K$. الطرف البعيد هو اللي بيحدد المعامل: $I/L$ لو ثابت، و $\\tfrac34 I/L$ لو مفصلي — و $\\tfrac12 I/L$ لكمرة إطار متماثل تحت حمل متماثل، لأن طرفيها بيلفوا بزاويتين متساويتين ومعكوستين (الإطار بيتقطع عند محور التماثل: $2EI/L$ بدل $4EI/L$)."}},{t:"eq",tex:["K_1 = \\dfrac{I}{L},\\qquad K_2 = \\dfrac{3}{4}\\,\\dfrac{I}{L},\\qquad K_3 = \\dfrac{1}{2}\\,\\dfrac{I}{L}","DF = \\dfrac{K}{\\Sigma K},\\qquad \\Sigma DF = 1"],caption:{en:"K₁: far end fixed; K₂: far end hinged; K₃: beam of a symmetric frame, symmetric load.",ar:"K₁: الطرف البعيد ثابت؛ و K₂: الطرف البعيد مفصلي؛ و K₃: كمرة إطار متماثل بحمل متماثل."}},{t:"table",head:[{en:"Frame",ar:"الإطار"},"K_b","K_c"],rows:[[{en:"two-hinged",ar:"ذو مفصلين"},"$\\tfrac12\\,I_b/L$","$\\tfrac34\\,I_c/h$"],[{en:"fixed bases",ar:"ثابت الركائز"},"$\\tfrac12\\,I_b/L$","$I_c/h$"]]},{t:"p",text:{en:"**Example — the 20 m hall** ($h = 7.5$ m, $I_b = 4.457\\,I_c$). Two-hinged: $K_c = 0.75/7.5 = 0.100\\,I_c$, $K_b = 0.5\\times4.457/20 = 0.1114\\,I_c$ → $DF_c = 0.100/0.2114 = 0.473$, $DF_b = 0.527$. Fixed bases: the column is prismatic and at least as deep as the beam, 400 × 1500, with $0.4\\times1.5^3/12 = 0.1125$ m⁴ $= 3.375\\,I_c$: $K_c = 3.375/7.5 = 0.45\\,I_c$ → $DF_c = 0.45/(0.45 + 0.1114) = 0.802$ — a fixed column is stiffer and takes a bigger share.",ar:"**مثال — صالة الـ 20 م** ($h = 7.5$ م، و $I_b = 4.457\\,I_c$). بمفصلين: $K_c = 0.75/7.5 = 0.100\\,I_c$، و $K_b = 0.5\\times4.457/20 = 0.1114\\,I_c$ ← $DF_c = 0.100/0.2114 = 0.473$، و $DF_b = 0.527$. بركائز ثابتة: العمود منشوري وعمقه على الأقل قد عمق الكمرة، 400 × 1500، وعزم قصوره $0.4\\times1.5^3/12 = 0.1125$ م⁴ $= 3.375\\,I_c$: $K_c = 3.375/7.5 = 0.45\\,I_c$ ← $DF_c = 0.45/(0.45 + 0.1114) = 0.802$ — العمود الثابت أجسأ وبياخد نصيب أكبر."}},{t:"quiz",q:{kind:"num",q:{en:"Two-hinged frame: L = 18 m, h = 6 m, I_b = 3 I_c. Distribution factor of the column?",ar:"إطار ذو مفصلين: L = 18 م، و h = 6 م، و I_b = 3 I_c. معامل توزيع العمود؟"},answer:.6,tol:.003,explain:{en:"$K_c = 0.75/6 = 0.125\\,I_c$, $K_b = 0.5\\times3/18 = 0.0833\\,I_c$ → $DF_c = 0.125/0.2083 = 0.60$.",ar:"$K_c = 0.75/6 = 0.125\\,I_c$، و $K_b = 0.5\\times3/18 = 0.0833\\,I_c$ ← $DF_c = 0.125/0.2083 = 0.60$."}}}]},{id:"fem",title:{en:"Fixed-end moments and the equivalent load",ar:"عزوم التثبيت والحمل المكافئ"},blocks:[{t:"table",head:[{en:"Load on the span",ar:"الحمل على البحر"},{en:"both ends fixed",ar:"الطرفين ثابتين"},{en:"far end hinged",ar:"الطرف البعيد مفصلي"}],rows:[[{en:"uniform w",ar:"حمل موزع منتظم w"},"$wL^2/12$","$wL^2/8$"],[{en:"P at mid-span",ar:"P في نص البحر"},"$PL/8$","$3PL/16$"],[{en:"P at a from the left (b = L − a)",ar:"P على بعد a من الشمال (b = L − a)"},"$Pab^2/L^2$ ; $Pa^2b/L^2$","—"]],caption:{en:"Fixed-end moments (F.E.M.) — hogging magnitudes at the ends.",ar:"عزوم التثبيت (F.E.M) — قيمها السالبة عند الأطراف."}},{t:"p",text:{en:"The frame beam carries the roof through secondary beams, so its load is a row of equal forces $P$ every $a$ metres. With three or more, they are smeared into a uniform load over the span, $w = w_g + \\Sigma P/L$, where $\\Sigma P$ counts only the secondary beams **inside the span**. The two that sit over the knees send their reactions straight down the columns: they add to $Y$ and give the beam no moment.",ar:"كمرة الإطار شايلة السقف عن طريق الكمرات المتشالة، فحملها صف من قوى متساوية $P$ كل $a$ متر. ولو هما تلاتة أو أكتر، بنفرشهم لحمل موزع منتظم على البحر، $w = w_g + \\Sigma P/L$، والـ $\\Sigma P$ بتعد الكمرات المتشالة اللي **جوه البحر** بس. والاتنين اللي فوق الأركان ردود أفعالهم بتنزل في الأعمدة على طول: بتزوّد $Y$ ومابتدّيش الكمرة عزم."}},{t:"eq",tex:["w = w_g + \\dfrac{\\Sigma P}{L},\\qquad M_{fe} = \\dfrac{wL^2}{12}","Y = \\dfrac{wL}{2} + P_e"],caption:{en:"w_g = own weight of the frame beam; ΣP = the reactions of the n − 1 secondary beams inside the span (n panels); P_e = the reaction of the edge secondary beam over the knee.",ar:"w_g = الوزن الذاتي لكمرة الإطار؛ و ΣP = ردود أفعال الـ n − 1 كمرة متشالة اللي جوه البحر (n باكية)؛ و P_e = رد فعل الكمرة المتشالة الطرفية اللي فوق الركن."}},{t:"note",tone:"info",text:{en:"Smearing is the standard hand route and fits best when the loads are many, roughly equal and evenly spaced. The real point loads have a somewhat larger fixed-end moment: n − 1 equal loads at L/n give M_fe = PL(n² − 1)/(12n), (n + 1)/n times their smeared value — 12.5% more for eight panels. Worth a glance when a few large loads dominate — with two heavy loads near the quarter points the gap grows: on a 24 m beam, 300 kN at 6 m from each knee and three 150 kN loads between them give M_fe = 2643.8 kN·m against the smeared 2100 kN·m (+26%).",ar:"الفرش هو الطريق اليدوي المعتاد، وأنسب ما يكون لما الأحمال تبقى كتير ومتساوية تقريباً ومتوزعة بانتظام. والأحمال المركزة الحقيقية عزم تثبيتها أكبر شوية: n − 1 حمل متساوي على L/n بيدّوا M_fe = PL(n² − 1)/(12n)، يعني (n + 1)/n من قيمتهم المفروشة — 12.5% زيادة لتمن بواكي. تستاهل نظرة لما كام حمل كبير يكونوا هما الغالبين — ولو حملين تقال قريبين من ربع البحر الفرق بيكبر قوي: على كمرة 24 م، 300 kN على بعد 6 م من كل ركن وتلات أحمال 150 kN بينهم بيدّوا M_fe = 2643.8 kN·m قصاد 2100 kN·m مفروشين (+26%)."}},{t:"p",text:{en:"**Example — loads of the 20 m hall** (ultimate, $1.4D + 1.6L$). Roof slab 120 mm with insulation and screed: $D = 3.0 + 3.0 = 6.0$, $L = 1.0$ kN/m² → $w_s = 10.0$ kN/m². Secondary beams 250 × 600 every $a = 2.5$ m — eight panels, seven beams on the span — frames $S = 6$ m apart: own weight $1.4\\times0.25\\times0.48\\times25 = 4.2$ kN/m, so each brings $P = (10.0\\times2.5 + 4.2)\\times6 = 175.2$ kN; the edge beam over each knee carries half a panel, $P_e = (10.0\\times1.25 + 4.2)\\times6 = 100.2$ kN, straight into the column. The frame beam weighs $1.4\\times0.4\\times1.38\\times25 = 19.32$ kN/m, so $w = 19.32 + 7\\times175.2/20 = 80.64$ kN/m, $M_{fe} = 80.64\\times20^2/12 = 2688$ kN·m and $Y = 80.64\\times10 + 100.2 = 906.6$ kN.",ar:"**مثال — أحمال صالة الـ 20 م** (أقصى، $1.4D + 1.6L$). بلاطة سقف 120 مم بعزل وميول: $D = 3.0 + 3.0 = 6.0$، و $L = 1.0$ kN/m² ← $w_s = 10.0$ kN/m². كمرات متشالة 250 × 600 كل $a = 2.5$ م — تمن بواكي، وسبع كمرات على البحر — والإطارات كل $S = 6$ م: وزنها $1.4\\times0.25\\times0.48\\times25 = 4.2$ kN/m، فكل واحدة بتجيب $P = (10.0\\times2.5 + 4.2)\\times6 = 175.2$ kN؛ والكمرة الطرفية اللي فوق كل ركن شايلة نص باكية، $P_e = (10.0\\times1.25 + 4.2)\\times6 = 100.2$ kN، بتنزل في العمود على طول. وكمرة الإطار وزنها $1.4\\times0.4\\times1.38\\times25 = 19.32$ kN/m، يبقى $w = 19.32 + 7\\times175.2/20 = 80.64$ kN/m، و $M_{fe} = 80.64\\times20^2/12 = 2688$ kN·m، و $Y = 80.64\\times10 + 100.2 = 906.6$ kN."}},{t:"p",text:{en:"**Other ways the roof reaches the frame beam.**",ar:"**طرق تانية السقف بيوصل بيها لكمرة الإطار.**"}},{t:"steps",items:[{en:"**Only two frames.** Secondary beams continuous over many frames hand every interior frame $R = w_a\\,S$. When only two frames carry the roof — a canopy or a loading bay on four corner columns — each secondary beam is a simple span between them, and each frame receives only $R = w_a\\,L_s/2$ ($L_s$ = the distance between the two frames). **Example:** a loading bay 20 × 8 m on four corner columns, frames along the 20 m sides, secondary beams every 2.5 m spanning the 8 m: $w_a = 4.2 + 9.0\\times2.5 = 26.7$ kN/m → $R = 26.7\\times8/2 = 106.8$ kN per secondary beam — half of the $26.7\\times8 = 213.6$ kN an interior frame of a long hall at the same spacing would get.",ar:"**إطارين بس.** الكمرات المتشالة المستمرة على إطارات كتير بتسلّم كل إطار داخلي $R = w_a\\,S$. ولو إطارين بس شايلين السقف — مظلة أو رصيف تحميل على أربع أعمدة في الأركان — كل كمرة متشالة بتبقى بحر بسيط بينهم، وكل إطار بياخد $R = w_a\\,L_s/2$ بس ($L_s$ = المسافة بين الإطارين). **مثال:** رصيف تحميل 20 × 8 م على أربع أعمدة في الأركان، والإطارات على ضلعين الـ 20 م، والكمرات المتشالة كل 2.5 م بحرها الـ 8 م: $w_a = 4.2 + 9.0\\times2.5 = 26.7$ kN/m ← $R = 26.7\\times8/2 = 106.8$ kN لكل كمرة متشالة — نص الـ $26.7\\times8 = 213.6$ kN اللي إطار داخلي في صالة طويلة بنفس المسافة كان هياخدهم."},{en:"**Slab panels bearing on the frame beam.** Two-way panels whose short side lies on the frame load it directly with their triangles: $w_e = o.w. + (\\Sigma A/L)\\,w_s$, $\\Sigma A$ = the triangles of all the panels on both sides along the span $L$. **Example:** an 18 m frame beam 400 × 1200 ($o.w. = 1.4\\times0.4\\times1.2\\times25 = 16.8$ kN/m), secondary beams every 4.5 m, frames 6 m apart: each 4.5 × 6 m panel sends $\\tfrac12\\times4.5\\times2.25 = 5.06$ m², eight of them line the span, $\\Sigma A/L = 40.5/18 = 2.25$ m; with $w_s = 8.0$ kN/m², $w_e = 16.8 + 2.25\\times8.0 = 34.8$ kN/m — plus the three inner secondary beams as point loads. A one-way hollow-block slab spanning from frame to frame gives $w = o.w. + (w_{rib}/S_r)\\,S$ ($S_r$ = rib spacing): ribs of 3.0 kN/m every 0.5 m between frames 5 m apart add $(3.0/0.5)\\times5 = 30$ kN/m.",ar:"**ألواح بلاطة قاعدة على كمرة الإطار.** الألواح اللي في اتجاهين وضلعها القصير قاعد على الإطار بتحمّله مباشرة بمثلثاتها: $w_e = o.w. + (\\Sigma A/L)\\,w_s$، و $\\Sigma A$ = مثلثات كل الألواح على الناحيتين على طول البحر $L$. **مثال:** كمرة إطار 18 م مقاسها 400 × 1200 ($o.w. = 1.4\\times0.4\\times1.2\\times25 = 16.8$ kN/m)، والكمرات المتشالة كل 4.5 م، والإطارات كل 6 م: كل لوح 4.5 × 6 م بيبعت $\\tfrac12\\times4.5\\times2.25 = 5.06$ م²، وتمنية منهم على طول البحر، $\\Sigma A/L = 40.5/18 = 2.25$ م؛ ومع $w_s = 8.0$ kN/m²، $w_e = 16.8 + 2.25\\times8.0 = 34.8$ kN/m — زائد التلات كمرات المتشالة اللي جوه كأحمال مركزة. والهوردي في اتجاه واحد اللي بحره من إطار لإطار بيدّي $w = o.w. + (w_{rib}/S_r)\\,S$ ($S_r$ = المسافة بين الأعصاب): أعصاب 3.0 kN/m كل 0.5 م بين إطارات كل 5 م بتزوّد $(3.0/0.5)\\times5 = 30$ kN/m."},{en:"**A sky-light raised on posts.** Each post brings three reactions: the transverse sky-light beam on the post line ($R_1 = w_1\\,b/2$, $b$ = width of the sky-light), the longitudinal sky-light edge beam ($R_2 = w_2\\,S$) and the edge beam of the main roof along the opening ($R_3 = w_3\\,S$): $P = R_1 + R_2 + R_3$. **Example:** a sky-light 4 m wide, beams of 12, 15 and 20 kN/m, frames every 6 m: $P = 12\\times4/2 + 15\\times6 + 20\\times6 = 24 + 90 + 120 = 234$ kN at each post.",ar:"**شخشيخة مرفوعة على قوائم.** كل قائم بيجيب تلات ردود أفعال: كمرة الشخشيخة العرضية اللي على خط القوائم ($R_1 = w_1\\,b/2$، و $b$ = عرض الشخشيخة)، وكمرة حرف الشخشيخة الطولية ($R_2 = w_2\\,S$)، والكمرة الطرفية للسقف الرئيسي على طول الفتحة ($R_3 = w_3\\,S$): $P = R_1 + R_2 + R_3$. **مثال:** شخشيخة عرضها 4 م، وكمرات 12 و 15 و 20 kN/m، والإطارات كل 6 م: $P = 12\\times4/2 + 15\\times6 + 20\\times6 = 24 + 90 + 120 = 234$ kN عند كل قائم."}]},{t:"eq",tex:["R = \\dfrac{w_a\\,L_s}{2},\\qquad w_e = o.w. + \\dfrac{\\Sigma A}{L}\\,w_s,\\qquad P = R_1 + R_2 + R_3"],caption:{en:"R: secondary beam simple between two frames only; w_e: two-way panels bearing on the frame beam; P: post of a raised sky-light.",ar:"R: كمرة متشالة بسيطة بين إطارين بس؛ و w_e: ألواح في اتجاهين قاعدة على كمرة الإطار؛ و P: قائم شخشيخة مرفوعة."}},{t:"quiz",q:{kind:"num",q:{en:"A 10 m fixed-ended beam carries P = 100 kN at 3 m from the left end. Fixed-end moment at the left end (kN·m)?",ar:"كمرة 10 م ثابتة الطرفين عليها P = 100 kN على بعد 3 م من الشمال. عزم التثبيت عند الطرف الشمال (kN·m)؟"},answer:147,tol:.003,unit:"kN·m",explain:{en:"$Pab^2/L^2 = 100\\times3\\times7^2/10^2 = 147$ kN·m (the right end: $Pa^2b/L^2 = 63$).",ar:"$Pab^2/L^2 = 100\\times3\\times7^2/10^2 = 147$ kN·m (والطرف اليمين: $Pa^2b/L^2 = 63$)."}}}]},{id:"balance",title:{en:"One balance at the knee",ar:"توازن واحد عند الركن"},blocks:[{t:"p",text:{en:"Symmetric frame, symmetric load: the knees turn but do not move sideways, the beam's far end is already in $K_b = \\tfrac12 I_b/L$ and the column's in $\\tfrac34$ or 1. So one balance at the knee is not a first step — it is the answer:",ar:"إطار متماثل وحمل متماثل: الأركان بتلف بس مابتتحركش جنب، والطرف البعيد للكمرة محسوب في $K_b = \\tfrac12 I_b/L$ وبتاع العمود في $\\tfrac34$ أو 1. يبقى توازن واحد عند الركن مش أول خطوة — ده الحل نفسه:"}},{t:"eq",tex:["M_F = M_{fe}\\,DF_c,\\qquad Y = \\dfrac{\\Sigma W}{2}","X = \\dfrac{M_F}{h};\\qquad M_{base} = \\dfrac{M_F}{2},\\quad X = \\dfrac{M_F + M_F/2}{h}","M_{mid} = \\dfrac{wL^2}{8} - M_F"],caption:{en:"Second line: two-hinged frame; fixed frame (the carry-over sends half the column moment, with the opposite sign, to the base).",ar:"السطر التاني: إطار ذو مفصلين؛ وإطار ثابت (الانتقال بيبعت نص عزم العمود، بإشارة عكسية، للقاعدة)."}},{t:"p",text:{en:"**The 20 m hall, two-hinged:** $M_F = 2688\\times0.473 = 1271.4$ kN·m, $X = 1271.4/7.5 = 169.5$ kN, $Y = 906.6$ kN, mid-span $80.64\\times20^2/8 - 1271.4 = 4032 - 1271.4 = 2760.6$ kN·m. **Fixed bases** (400 × 1500 columns): $M_F = 2688\\times0.802 = 2154.5$ kN·m, $M_{base} = 1077.3$ kN·m, $X = (2154.5 + 1077.3)/7.5 = 430.9$ kN, mid-span 1877.5 kN·m. Fixing the bases on deep prismatic columns moves 883 kN·m from the span to the knees — and sends 1077.3 kN·m into each footing.",ar:"**صالة الـ 20 م بمفصلين:** $M_F = 2688\\times0.473 = 1271.4$ kN·m، و $X = 1271.4/7.5 = 169.5$ kN، و $Y = 906.6$ kN، ونص البحر $80.64\\times20^2/8 - 1271.4 = 4032 - 1271.4 = 2760.6$ kN·m. **بركائز ثابتة** (أعمدة 400 × 1500): $M_F = 2688\\times0.802 = 2154.5$ kN·m، و $M_{base} = 1077.3$ kN·m، و $X = (2154.5 + 1077.3)/7.5 = 430.9$ kN، ونص البحر 1877.5 kN·m. تثبيت الركائز على أعمدة منشورية عميقة بينقل 883 kN·m من البحر للأركان — وبيبعت 1077.3 kN·m لكل قاعدة."}},{t:"p",text:{en:"Draw them on the tension side: the knees hog on the outside (the column's outer face and the beam's top), the span sags below. In a two-hinged column $M$ grows linearly from zero at the hinge to $M_F$; a fixed column changes sign $h/3$ above its base. N.F.D.: each column $-Y$, the beam $-X$. The lab solves the same frame by the stiffness method with the seven real point loads: 1389.7 kN·m at the knee, 9% above the smeared 1271.4 — the fixed-end moment of the real loads is 2943.5 instead of 2688 kN·m (the note above).",ar:"ارسمهم ناحية الشد: الأركان بعزم سالب من بره (الوش الخارجي للعمود وفوق الكمرة)، والبحر بعزم موجب تحت. في العمود ذو المفصلة $M$ بيكبر خطياً من صفر عند المفصلة لحد $M_F$؛ والعمود الثابت بيغيّر إشارته على ارتفاع $h/3$ من قاعدته. ومنحنى القوى العمودية: كل عمود $-Y$ والكمرة $-X$. والمعمل بيحل نفس الإطار بطريقة الجساءة بالسبع أحمال المركزة الحقيقية: 1389.7 kN·m عند الركن، أعلى من المفروش 1271.4 بـ 9% — عزم تثبيت الأحمال الحقيقية 2943.5 بدل 2688 kN·m (الملحوظة اللي فوق)."}},{t:"p",text:{en:"**A continuous frame of two equal bays** (three hinged columns) is solved the same way only when it is **symmetric**, frame and load: then the middle joint does not turn, so take half the frame with the middle joint fixed. At the edge knee the column has $K_c = \\tfrac34 I_c/h$ and the beam, its far end now fixed, $K_b = I_b/L$; one balance at the knee and one carry-over of half the beam's balancing moment to the middle joint finish the table. The middle column takes no moment under the symmetric load. The span moment is taken at mid-span, $wL^2/8 - (M_1 + M_2)/2$. **Example:** two bays of 16 m, $h = 6$ m, $I_b = 2I_c$, $w = 50$ kN/m: $K_c = 0.75/6 = 0.125\\,I_c$ and $K_b = 2/16 = 0.125\\,I_c$ → $DF = 0.5$ each; $M_{fe} = 50\\times16^2/12 = 1066.7$ kN·m. Edge knee $0.5\\times1066.7 = 533.3$ kN·m; over the middle column $1066.7 + 533.3/2 = 1333.3$ kN·m; mid-span $1600 - (533.3 + 1333.3)/2 = 666.7$ kN·m (the true maximum, 7.0 m from the edge knee, is 691.7). Edge hinges $X = 533.3/6 = 88.9$ kN; the middle column carries $N = 2\\times(400 + 50) = 900$ kN.",ar:"**الإطار المستمر بباكيتين متساويتين** (تلات أعمدة مفصلية) بيتحل بنفس الطريقة بس لو كان **متماثل**، الإطار والحمل: ساعتها العقدة اللي في النص مابتلفش، فخد نص الإطار والعقدة اللي في النص ثابتة. عند الركن الطرفي العمود ليه $K_c = \\tfrac34 I_c/h$ والكمرة، وطرفها البعيد بقى ثابت، $K_b = I_b/L$؛ وتوازن واحد عند الركن وانتقال واحد لنص عزم الاتزان بتاع الكمرة للعقدة اللي في النص بيخلّصوا الجدول. والعمود اللي في النص مابياخدش عزم تحت الحمل المتماثل. وعزم البحر بيتاخد في نصه، $wL^2/8 - (M_1 + M_2)/2$. **مثال:** باكيتين 16 م، و $h = 6$ م، و $I_b = 2I_c$، و $w = 50$ kN/m: $K_c = 0.75/6 = 0.125\\,I_c$ و $K_b = 2/16 = 0.125\\,I_c$ ← $DF = 0.5$ لكل واحد؛ و $M_{fe} = 50\\times16^2/12 = 1066.7$ kN·m. الركن الطرفي $0.5\\times1066.7 = 533.3$ kN·m؛ وفوق العمود اللي في النص $1066.7 + 533.3/2 = 1333.3$ kN·m؛ ونص البحر $1600 - (533.3 + 1333.3)/2 = 666.7$ kN·m (وأكبر قيمة حقيقية، على بعد 7.0 م من الركن الطرفي، 691.7). والمفصلات الطرفية $X = 533.3/6 = 88.9$ kN؛ والعمود اللي في النص شايل $N = 2\\times(400 + 50) = 900$ kN."}},{t:"p",text:{en:"**Its middle column** carries $N$ only under the symmetric load, yet it is cast rigidly with the beam — it is not a link member. Give it the depth of the beam at its top, tapered to $t/2$ at its hinge, and at least $0.8\\%$ of $b\\,t$, half on each face, anchored $L_d$ into the beam: unequal live loads on the two bays bend it one way or the other. Under a 400 × 1200 beam: $0.008\\times400\\times1200 = 3840$ mm², 1920 mm² a face → 4Ø25 (1963 mm²) on each face.",ar:"**العمود اللي في النص** شايل $N$ بس تحت الحمل المتماثل، ومع ذلك مصبوب مع الكمرة جاسئ — مش وصلة. ادّيله عمق الكمرة عند راسه، متدرّج لـ $t/2$ عند مفصلته، وعلى الأقل $0.8\\%$ من $b\\,t$، نصهم على كل وش ومتثبتين $L_d$ جوه الكمرة: لأن الأحمال الحية المختلفة على الباكيتين بتحنيه في اتجاه أو التاني. تحت كمرة 400 × 1200: $0.008\\times400\\times1200 = 3840$ مم²، يعني 1920 مم² لكل وش ← 4Ø25 (1963 مم²) على كل وش."}},{t:"lab",lab:"frame",height:480,props:{template:"hall",lockTemplate:!0,defaultTab:"hand",missions:c},caption:{en:"The 20 m hall: T-beam 400 × 1500, tapered columns 400 × 1200, seven secondary beams. Change the bases, the slab and the column model; the Hand method tab repeats the one-balance solution with your numbers.",ar:"صالة الـ 20 م: كمرة T مقاس 400 × 1500، وأعمدة متدرّجة 400 × 1200، وسبع كمرات متشالة. غيّر الركائز والبلاطة وتمثيل العمود؛ وتبويب الحل اليدوي بيعيد حل التوازن الواحد بأرقامك."}},{t:"quiz",q:{kind:"num",q:{en:"Fixed-base hall: M_F = 600 kN·m at the knee, h = 5 m. Horizontal reaction X (kN)?",ar:"صالة ثابتة الركائز: M_F = 600 kN·m عند الركن، و h = 5 م. رد الفعل الأفقي X (kN)؟"},answer:180,tol:.003,unit:"kN",explain:{en:"$M_{base} = 300$ → $X = (600 + 300)/5 = 180$ kN.",ar:"$M_{base} = 300$ ← $X = (600 + 300)/5 = 180$ kN."}}}]},{id:"cantilever",title:{en:"A cantilever outside the knee",ar:"كابولي بره الركن"},blocks:[{t:"p",text:{en:"Halls often carry a canopy or a gallery on cantilevers beyond the columns. The cantilever is statically determinate: its moment at the knee, $M_c = w_c c^2/2$ (+ $P_c c$), is known before any distribution. It pulls against the beam's fixed-end moment, so the knee balances only what is left, and the joint shares its three moments:",ar:"الصالات كتير بتشيل مظلة أو بلكونة على كوابيل بره الأعمدة. الكابولي محدد استاتيكياً: عزمه عند الركن، $M_c = w_c c^2/2$ (+ $P_c c$)، معروف قبل أي توزيع. وبيشد عكس عزم تثبيت الكمرة، فالركن بيوزّع اللي فاضل بس، والعقدة بتقسم عزومها التلاتة:"}},{t:"eq",tex:["M_{col} = DF_c\\,\\left(M_{fe} - M_c\\right)","M_{knee} = M_{col} + M_c,\\qquad M_{mid} = \\dfrac{wL^2}{8} - M_{knee}"],caption:{en:"With fixed bases the base again takes M_col/2.",ar:"ولو الركائز ثابتة القاعدة بتاخد تاني M_col/2."}},{t:"p",text:{en:"With a cantilever at the knee the single product $M_F = M_{fe}\\cdot DF_c$ no longer holds: the moments at the joint come from a distribution table — the balance of $M_{fe} - M_c$ above is that table in one line — or from virtual work. Up to $L_c = 2.0$ m the overhang is a cantilever slab hanging on an edge beam, whose torsion reaches each column as a concentrated moment $w_s L_c^2 S/2$ at the slab level (the miscellaneous-systems episode); beyond 2.0 m it is a cantilever frame, an arm cast with every column, as here.",ar:"ومع كابولي عند الركن حاصل الضرب لوحده $M_F = M_{fe}\\cdot DF_c$ مبقاش ينفع: العزوم عند العقدة بتطلع من جدول توزيع — واتزان $M_{fe} - M_c$ اللي فوق هو الجدول ده في سطر واحد — أو من الشغل الافتراضي. ولحد $L_c = 2.0$ م الكابولي بيبقى بلاطة كابولي متعلقة على كمرة طرفية، والتواؤها بيوصل لكل عمود كعزم مركز $w_s L_c^2 S/2$ عند منسوب البلاطة (حلقة الأنظمة المتنوعة)؛ وبعد 2.0 م بيبقى إطار كابولي، ذراع مصبوب مع كل عمود، زي هنا."}},{t:"note",tone:"tip",text:{en:"Quick route for a symmetric frame: solve it without the cantilever, M₁ = M_fe·DF_c, then add the cantilever at the knee, M_F = M₁ + M_c. Against the table it gives the beam end DF_c·M_c too much (on the safe side) and the mid-span the same amount too little — keep it for a first size.",ar:"طريق سريع لإطار متماثل: حلّه من غير الكابولي، M₁ = M_fe·DF_c، وبعدين زوّد الكابولي عند الركن، M_F = M₁ + M_c. وقصاد الجدول بيدّي طرف الكمرة DF_c·M_c زيادة (في الأمان) ونص البحر نفس القيمة ناقصة — استخدمه لأول تكبير للقطاعات."}},{t:"p",text:{en:"**Example:** the 20 m hall with 3 m cantilevers carrying 40 kN/m: $M_c = 40\\times3^2/2 = 180$ kN·m. $M_{col} = 0.473\\times(2688 - 180) = 1186.3$ kN·m, the beam end keeps $1186.3 + 180 = 1366.3$ kN·m, mid-span $4032 - 1366.3 = 2665.7$ kN·m, $X = 1186.3/7.5 = 158.2$ kN and $Y = 906.6 + 120 = 1026.6$ kN. The quick route gives $1271.4 + 180 = 1451.4$ kN·m at the beam end ($85.1 = 0.473\\times180$ more) and $2580.6$ kN·m at mid-span. The cantilever relieves the column and the span and loads the beam end. If $M_c$ exceeds $M_{fe}$ the column moment reverses: tension on its inner face.",ar:"**مثال:** صالة الـ 20 م بكوابيل 3 م عليها 40 kN/m: $M_c = 40\\times3^2/2 = 180$ kN·m. و $M_{col} = 0.473\\times(2688 - 180) = 1186.3$ kN·m، وطرف الكمرة بياخد $1186.3 + 180 = 1366.3$ kN·m، ونص البحر $4032 - 1366.3 = 2665.7$ kN·m، و $X = 1186.3/7.5 = 158.2$ kN و $Y = 906.6 + 120 = 1026.6$ kN. والطريق السريع بيدّي $1271.4 + 180 = 1451.4$ kN·m عند طرف الكمرة ($85.1 = 0.473\\times180$ زيادة) و $2580.6$ kN·m في نص البحر. الكابولي بيريّح العمود والبحر وبيحمّل طرف الكمرة. ولو $M_c$ عدّى $M_{fe}$ عزم العمود بيعكس: الشد على وشه الداخلي."}},{t:"lab",lab:"frame",height:480,props:{template:"hall",params:{c:3,wc:40},lockTemplate:!0,defaultTab:"structure",missions:f},caption:{en:"The same hall with 3 m cantilevers. Change c, w_c and the span loads; select a knee to read the three moments that meet there.",ar:"نفس الصالة بكوابيل 3 م. غيّر c و w_c وأحمال البحر؛ واختار ركن تقرا العزوم التلاتة اللي بتتقابل عنده."}},{t:"quiz",q:{kind:"num",q:{en:"M_fe = 1200 kN·m, cantilever M_c = 300 kN·m, DF_c = 0.5. Beam end moment at the knee (kN·m)?",ar:"M_fe = 1200 kN·m، وعزم الكابولي M_c = 300 kN·m، و DF_c = 0.5. عزم طرف الكمرة عند الركن (kN·m)؟"},answer:750,tol:.003,unit:"kN·m",explain:{en:"$M_{col} = 0.5\\times(1200 - 300) = 450$; $M_{knee} = 450 + 300 = 750$ kN·m.",ar:"$M_{col} = 0.5\\times(1200 - 300) = 450$؛ و $M_{knee} = 450 + 300 = 750$ kN·m."}}}]},{id:"vw",title:{en:"Virtual work: the gable frame",ar:"الشغل الافتراضي: الإطار الجمالوني"},blocks:[{t:"p",text:{en:"In a gable frame the ridge drops and the knees spread, so the distribution would need sway corrections. Use the force method with one redundant, the horizontal thrust $X$ at the hinges: release it (one hinge becomes a roller) and draw $M_0$ of the determinate frame; apply $X = 1$ and draw $M_1 = -y$ ($y$ = height above the hinges); then close the gap:",ar:"في الإطار الجمالوني التاج بينزل والأركان بتفتح، فالتوزيع هيحتاج تصحيحات للحركة الجانبية. استخدم طريقة القوى بمجهول زائد واحد، الدفع الأفقي $X$ عند المفصلات: فكّه (مفصلة واحدة تبقى متحركة) وارسم $M_0$ للإطار المحدد؛ وبعدين حط $X = 1$ وارسم $M_1 = -y$ ($y$ = الارتفاع فوق المفصلات)؛ وبعدين اقفل الفتحة:"}},{t:"eq",tex:["\\delta_{10} = \\Sigma\\int\\dfrac{M_0\\,M_1}{EI}\\,ds,\\qquad \\delta_{11} = \\Sigma\\int\\dfrac{M_1^2}{EI}\\,ds","\\delta_{10} + X\\,\\delta_{11} = 0,\\qquad M = M_0 + X\\,M_1"]},{t:"table",head:[{en:"Diagrams multiplied over a length s",ar:"المنحنيين المضروبين على طول s"},"∫ Mᵢ·Mₖ ds"],rows:[[{en:"rectangle × rectangle",ar:"مستطيل × مستطيل"},"$1\\cdot s\\,M_i M_k$"],[{en:"rectangle × triangle",ar:"مستطيل × مثلث"},"$\\tfrac12\\, s\\,M_i M_k$"],[{en:"triangle × triangle, peaks at the same end",ar:"مثلث × مثلث، القمتين في نفس الطرف"},"$\\tfrac13\\, s\\,M_i M_k$"],[{en:"triangle × triangle, peaks at opposite ends",ar:"مثلث × مثلث، القمتين في طرفين عكس"},"$\\tfrac16\\, s\\,M_i M_k$"],[{en:"triangle × symmetric parabola",ar:"مثلث × قطع مكافئ متماثل"},"$\\tfrac13\\, s\\,M_i M_k$"],[{en:"rectangle × symmetric parabola",ar:"مستطيل × قطع مكافئ متماثل"},"$\\tfrac23\\, s\\,M_i M_k$"],[{en:"trapezoid (a → b) × trapezoid (c → d)",ar:"شبه منحرف (a ← b) × شبه منحرف (c ← d)"},"$\\tfrac{s}{6}\\,(2ac + 2bd + ad + bc)$"],[{en:"trapezoid (a → b) × parabola of mid ordinate m",ar:"شبه منحرف (a ← b) × قطع مكافئ ارتفاعه في النص m"},"$\\tfrac{s}{3}\\,m\\,(a + b)$"]]},{t:"p",text:{en:"On a rafter $M_0$ is a triangle from 0 at the knee to $wL^2/8$ at the ridge plus a parabola of mid ordinate $wL^2/32$; $M_1$ is a trapezoid from $-h$ to $-(h + f)$. Work in $EI_c$ units: rafter integrals are divided by $n = I_b/I_c$.",ar:"على الكمرة المائلة $M_0$ مثلث من صفر عند الركن لحد $wL^2/8$ عند التاج زائد قطع مكافئ ارتفاعه في النص $wL^2/32$؛ و $M_1$ شبه منحرف من $-h$ لحد $-(h + f)$. اشتغل بوحدات $EI_c$: تكاملات الكمرات المائلة بتتقسم على $n = I_b/I_c$."}},{t:"p",text:{en:"**Example.** $L = 16$ m, $h = 6$ m, $f = 2$ m ($s = 8.246$ m), $w = 30$ kN/m on plan; rafters 400 × 1000 under a 120 mm slab ($\\mu = 421$ → $I_b = 0.0472$ m⁴), columns 400 × 900 tapered ($I_c = 0.4\\times0.75^3/12 = 0.01406$ m⁴) → $n = 3.356$; $M_0 = 30\\times16^2/8 = 960$ kN·m. $EI_c\\,\\delta_{11} = 2\\,[6^3/3 + 8.246\\times(2\\times36 + 2\\times64 + 2\\times48)/(6\\times3.356)] = 2\\,(72 + 121.22) = 386.44$. $EI_c\\,\\delta_{10} = -\\tfrac{2}{3.356}\\,[\\tfrac{8.246}{6}\\times960\\times(16 + 6) + \\tfrac{8.246}{3}\\times240\\times(12 + 2)] = -22802.9$. $X = 22802.9/386.44 = 59.0$ kN. Knee $59.0\\times6 = 354.0$ kN·m; ridge $960 - 59.0\\times8 = 487.9$ kN·m. Normal forces: columns 240 kN; rafters $59.0\\times0.970 + 240\\times0.243 = 115.5$ kN at the knee and $57.2$ kN at the ridge. The lab gives $X = 58.9$ kN.",ar:"**مثال.** $L = 16$ م، و $h = 6$ م، و $f = 2$ م ($s = 8.246$ م)، و $w = 30$ kN/m على المسقط؛ كمرات مائلة 400 × 1000 تحت بلاطة 120 مم ($\\mu = 421$ ← $I_b = 0.0472$ م⁴)، وأعمدة 400 × 900 متدرّجة ($I_c = 0.4\\times0.75^3/12 = 0.01406$ م⁴) ← $n = 3.356$؛ و $M_0 = 30\\times16^2/8 = 960$ kN·m. و $EI_c\\,\\delta_{11} = 2\\,[6^3/3 + 8.246\\times(2\\times36 + 2\\times64 + 2\\times48)/(6\\times3.356)] = 2\\,(72 + 121.22) = 386.44$. و $EI_c\\,\\delta_{10} = -\\tfrac{2}{3.356}\\,[\\tfrac{8.246}{6}\\times960\\times(16 + 6) + \\tfrac{8.246}{3}\\times240\\times(12 + 2)] = -22802.9$. و $X = 22802.9/386.44 = 59.0$ kN. الركن $59.0\\times6 = 354.0$ kN·m؛ والتاج $960 - 59.0\\times8 = 487.9$ kN·m. القوى العمودية: الأعمدة 240 kN؛ والكمرات المائلة $59.0\\times0.970 + 240\\times0.243 = 115.5$ kN عند الركن و $57.2$ kN عند التاج. والمعمل بيدّي $X = 58.9$ kN."}},{t:"p",text:{en:"**Reading the integrals as area × ordinate.** When one of the two diagrams is a straight line, $\\int M_i M_k\\,ds$ is simply the **area** of the other times the ordinate of the straight one under its **centroid** — two thirds along a triangle from its zero end, the middle of a symmetric parabola. In the example the rafter triangle has the area $\\tfrac12\\times8.246\\times960 = 3958.1$ and its centroid two thirds of the way to the ridge, where $|M_1| = y = 6 + \\tfrac23\\times2 = 7.33$: $3958.1\\times7.33 = 29026$; the parabola has $\\tfrac23\\times8.246\\times240 = 1319.4$ at the middle, $|M_1| = 7$: $9235.5$ — the two table entries. **Shear and normal force in a rafter** of slope θ, with $V$ the shear of the simple beam at that section: $N = X\\cos\\theta + V\\sin\\theta$ and $Q = V\\cos\\theta - X\\sin\\theta$. At the knee of the example $Q = 240\\times0.970 - 59.0\\times0.243 = 218.5$ kN; at the ridge $V = 0$ and $Q = -59.0\\times0.243 = -14.3$ kN. A gable whose two eaves differ a little in level is, for a hand solution, idealised as symmetric — both columns as tall as the higher one — and solved with one redundant.",ar:"**التكاملات كمساحة × ارتفاع.** لما واحد من المنحنيين يبقى خط مستقيم، $\\int M_i M_k\\,ds$ ببساطة **مساحة** التاني مضروبة في ارتفاع الخط المستقيم تحت **مركز ثقله** — التلتين على المثلث من طرفه الصفر، ونص القطع المكافئ المتماثل. في المثال مثلث الكمرة المائلة مساحته $\\tfrac12\\times8.246\\times960 = 3958.1$ ومركز ثقله على تلتين المسافة ناحية التاج، وهناك $|M_1| = y = 6 + \\tfrac23\\times2 = 7.33$: $3958.1\\times7.33 = 29026$؛ والقطع المكافئ مساحته $\\tfrac23\\times8.246\\times240 = 1319.4$ في النص، و $|M_1| = 7$: $9235.5$ — نفس قيمتين الجدول. **القص والقوة العمودية في الكمرة المائلة** بميل θ، و $V$ قص الكمرة البسيطة عند القطاع ده: $N = X\\cos\\theta + V\\sin\\theta$ و $Q = V\\cos\\theta - X\\sin\\theta$. عند ركن المثال $Q = 240\\times0.970 - 59.0\\times0.243 = 218.5$ kN؛ وعند التاج $V = 0$ و $Q = -59.0\\times0.243 = -14.3$ kN. والجمالوني اللي ركنيه بينهم فرق منسوب صغير بيتمثّل في الحل اليدوي متماثل — العمودين بطول الأعلى فيهم — وبيتحل بمجهول زائد واحد."}},{t:"p",text:{en:"**Tied gables.** A tie at the **eaves** takes the thrust out of the columns: on a hinge and a roller the gable works as a girder, solved by virtual work with the tie force $T$ as the redundant ($M_1 = -y'$ on the rafters, $y'$ = height above the eaves; the columns carry no moment). For a rigid tie and a uniform load on plan it closes neatly: the ridge then hogs by $wL^2/32$ whatever the rise. **Example:** $L = 16$ m, $f = 2.5$ m, $w = 30$ kN/m: $T = 5\\times30\\times16^2/(32\\times2.5) = 480$ kN, ridge $960 - 480\\times2.5 = -240$ kN·m, largest sagging 135 kN·m at 3 m (on plan) from each knee. On two hinges a tie that stretches lets the knees spread a little and gives the columns a small moment: no footing shift is needed, but continue the rafter bars down into the columns against cracking. A **hanger from the apex** keeps a long tie from sagging. A tie at **foundation level** between the hinged feet leaves the gable its knee moments, but the footings receive $Y$ only — no shift.",ar:"**الإطارات الجمالونية بشداد.** الشداد عند **منسوب الأركان** بيشيل الدفع من الأعمدة: على ركيزة مفصلية ومتحركة الجمالوني بيشتغل كمرة، وبيتحل بالشغل الافتراضي وقوة الشداد $T$ هي المجهول الزائد ($M_1 = -y'$ على الكمرات المائلة، و $y'$ = الارتفاع فوق الأركان؛ والأعمدة مفيهاش عزم). ولو الشداد جاسئ والحمل موزع منتظم على المسقط الحل بيطلع بسيط: التاج بياخد عزم سالب $wL^2/32$ مهما كان الارتفاع. **مثال:** $L = 16$ م، و $f = 2.5$ م، و $w = 30$ kN/m: $T = 5\\times30\\times16^2/(32\\times2.5) = 480$ kN، والتاج $960 - 480\\times2.5 = -240$ kN·m، وأكبر عزم موجب 135 kN·m على بعد 3 م (على المسقط) من كل ركن. وعلى مفصلتين، الشداد اللي بيستطيل بيخلّي الأركان تفتح سنة وبيدّي الأعمدة عزم صغير: مش محتاجين ترحيل للقواعد، بس كمّل أسياخ الكمرات المائلة لتحت جوه الأعمدة ضد الشروخ. و**معلّق من التاج** بيمنع الشداد الطويل إنه يترخّم. والشداد عند **منسوب القواعد** بين الرجلين المفصليين بيسيب للجمالوني عزوم أركانه، بس القواعد بتاخد $Y$ بس — من غير ترحيل."}},{t:"eq",tex:["T = \\dfrac{5\\,wL^2}{32\\,f},\\qquad M_{ridge} = \\dfrac{wL^2}{8} - T\\,f = -\\dfrac{wL^2}{32}"],caption:{en:"Gable tied at the eaves on a hinge and a roller: rigid tie, straight rafters of equal inertia, uniform load w on plan, rise f.",ar:"جمالوني بشداد عند الأركان على ركيزة مفصلية ومتحركة: شداد جاسئ، وكمرات مائلة مستقيمة بنفس عزم القصور، وحمل موزع منتظم w على المسقط، وارتفاع f."}},{t:"lab",lab:"frame",height:480,props:{template:"hallgable",lockTemplate:!0,defaultTab:"hand",missions:k},caption:{en:"The gable hall of the example. The Hand method tab builds δ₁₀ and δ₁₁ from the product table; try fixed bases and a tie at the knees too.",ar:"الصالة الجمالونية بتاعة المثال. تبويب الحل اليدوي بيبني δ₁₀ و δ₁₁ من جدول الضرب؛ وجرّب الركائز الثابتة والشداد عند الأركان كمان."}},{t:"quiz",q:{kind:"num",q:{en:"Two triangular diagrams over s = 5 m, peaks 4 and 6 at the same end. ∫Mᵢ·Mₖ ds?",ar:"منحنيين مثلثين على طول s = 5 م، وقمتهم 4 و 6 في نفس الطرف. ∫Mᵢ·Mₖ ds؟"},answer:40,tol:.003,explain:{en:"$\\tfrac13\\times5\\times4\\times6 = 40$.",ar:"$\\tfrac13\\times5\\times4\\times6 = 40$."}}}]},{id:"approx",title:{en:"Approximate methods: hinges at L/5 and at H/3",ar:"الحلول التقريبية: مفصلات عند L/5 و H/3"},blocks:[{t:"p",text:{en:"When time is short, put imaginary hinges where the moment is expected to vanish, and the frame becomes determinate:",ar:"لما الوقت يبقى ضيق، حُط مفصلات وهمية في الأماكن اللي متوقع العزم فيها يبقى صفر، والإطار بيبقى محدد:"}},{t:"steps",items:[{en:"**Two-hinged frame: beam hinges at L/5** from each knee (a fixed-ended beam has its inflection points at 0.21L): the middle 3L/5 is a simple beam hung on two short cantilevers — $M_{knee} = 0.08\\,wL^2$, $M_{mid} = 0.045\\,wL^2$, and the thrust $X = 0.08\\,wL^2/H$.",ar:"**الإطار ذو المفصلين: مفصلات في الكمرة عند L/5** من كل ركن (الكمرة ثابتة الطرفين نقط انقلاب عزمها عند 0.21L): الـ 3L/5 اللي في النص كمرة بسيطة متعلقة على كابولين قصيرين — $M_{knee} = 0.08\\,wL^2$ و $M_{mid} = 0.045\\,wL^2$، والدفع $X = 0.08\\,wL^2/H$."},{en:"**Fixed frame: add a hinge in each column at H/3** above its base (a fixed column bends back there). With the beam hinges at L/5 the rest is a two-hinged frame of height 2H/3: $M_{knee} = 0.08\\,wL^2$, $X = 0.08\\,wL^2/(2H/3) = 0.12\\,wL^2/H$ and $M_{base} = X\\,H/3 = 0.04\\,wL^2$ — half the knee moment, as the distribution gives.",ar:"**الإطار الثابت: ضيف مفصلة في كل عمود عند H/3** من قاعدته (العمود الثابت بيعكس انحناءه هناك). ومع مفصلات الكمرة عند L/5 الباقي إطار ذو مفصلين ارتفاعه 2H/3: $M_{knee} = 0.08\\,wL^2$، و $X = 0.08\\,wL^2/(2H/3) = 0.12\\,wL^2/H$، و $M_{base} = X\\,H/3 = 0.04\\,wL^2$ — نص عزم الركن، زي ما التوزيع بيدّي."},{en:"**Two-hinged gable: rafter hinges at L/5** (measured on plan) from each knee, at the height $h + 0.4f$: $X = 0.08\\,wL^2/(h + 0.4f)$, $M_{knee} = X\\,h$, $M_{ridge} = wL^2/8 - X\\,(h + f)$.",ar:"**الجمالوني ذو المفصلين: مفصلات في الكمرات المائلة عند L/5** (على المسقط) من كل ركن، على ارتفاع $h + 0.4f$: $X = 0.08\\,wL^2/(h + 0.4f)$، و $M_{knee} = X\\,h$، و $M_{ridge} = wL^2/8 - X\\,(h + f)$."},{en:"**Fixed gable: both sets of hinges at once** — H/3 in the columns, L/5 in the rafters — and the frame is fully determinate: $X = 0.08\\,wL^2/(2h/3 + 0.4f)$, $M_{knee} = X\\cdot2h/3$, $M_{base} = X\\,h/3$, $M_{ridge} = wL^2/8 - X\\,(2h/3 + f)$. A closer variant keeps only the H/3 hinges and solves the remaining two-hinged gable of column height 2H/3 by virtual work; its base moment is again $X\\cdot H/3$.",ar:"**الجمالوني الثابت: المجموعتين من المفصلات مع بعض** — H/3 في الأعمدة و L/5 في الكمرات المائلة — والإطار بيبقى محدد بالكامل: $X = 0.08\\,wL^2/(2h/3 + 0.4f)$، و $M_{knee} = X\\cdot2h/3$، و $M_{base} = X\\,h/3$، و $M_{ridge} = wL^2/8 - X\\,(2h/3 + f)$. وفيه طريقة أقرب بتسيب مفصلات H/3 بس وبتحل الجمالوني ذو المفصلين اللي فاضل بارتفاع عمود 2H/3 بالشغل الافتراضي؛ وعزم قاعدته برضه $X\\cdot H/3$."}]},{t:"eq",tex:["X_1 = \\dfrac{0.08\\,wL^2}{H},\\qquad X_2 = \\dfrac{0.12\\,wL^2}{H},\\qquad X_3 = \\dfrac{0.08\\,wL^2}{h + 0.4f},\\qquad X_4 = \\dfrac{0.08\\,wL^2}{2h/3 + 0.4f}","M_{knee} = X\\,h_e,\\qquad M_{base} = X\\,\\dfrac{h}{3},\\qquad M_{ridge} = \\dfrac{wL^2}{8} - X\\,(h_e + f)"],caption:{en:"X₁ two-hinged frame, X₂ fixed frame, X₃ two-hinged gable, X₄ fixed gable (rise f); h_e = the column height above the hinges: h for two hinges at the base, 2h/3 for a fixed base; M_base for fixed bases only.",ar:"X₁ إطار ذو مفصلين، و X₂ إطار ثابت، و X₃ جمالوني ذو مفصلين، و X₄ جمالوني ثابت (ارتفاعه f)؛ و h_e = ارتفاع العمود فوق المفصلات: h للمفصلتين عند القاعدة، و 2h/3 للركيزة الثابتة؛ و M_base للركائز الثابتة بس."}},{t:"p",text:{en:"They are very approximate — use them when time runs out, and check them before you trust them. The L/5 hinges assume columns much stiffer than the beam. The 20 m hall has slender columns and a real knee moment of $0.039\\,wL^2$; the hinges predict $0.08\\times80.64\\times20^2 = 2580.5$ kN·m — twice the 1271.4. With its fixed 400 × 1500 columns they give $X = 0.12\\times80.64\\times20^2/7.5 = 516.1$ kN and 1290.2 kN·m at the base against the 430.9 kN and 1077.3 kN·m of the one balance. The gable of the virtual-work example: on two hinges $X = 0.08\\times30\\times16^2/(6 + 0.8) = 90.4$ kN, knee 542.1 and ridge 237.2 kN·m against the exact 59.0, 354.0 and 487.9. With fixed 400 × 900 columns ($n = 1.942$) both sets of hinges give $X = 614.4/4.8 = 128.0$ kN, knee 512.0, base 256.0 and ridge 192.0 kN·m against the exact 118.0 kN, 423.7, 284.5 and 300.3 kN·m; the closer H/3 variant gives $X = 110.7$ kN, knee 442.7, ridge 295.9 — but only 221.4 kN·m at the base, because the knees also spread.",ar:"دي حلول تقريبية جداً — استخدمها لما الوقت يخلص، وراجعها قبل ما تصدقها. مفصلات L/5 فارضة أعمدة أجسأ بكتير من الكمرة. صالة الـ 20 م أعمدتها نحيفة وعزم ركنها الحقيقي $0.039\\,wL^2$؛ والمفصلات بتتوقع $0.08\\times80.64\\times20^2 = 2580.5$ kN·m — ضعف الـ 1271.4. وبأعمدتها الثابتة 400 × 1500 بتدّي $X = 0.12\\times80.64\\times20^2/7.5 = 516.1$ kN و 1290.2 kN·m عند القاعدة قصاد 430.9 kN و 1077.3 kN·m من التوازن الواحد. وجمالوني مثال الشغل الافتراضي: على مفصلتين $X = 0.08\\times30\\times16^2/(6 + 0.8) = 90.4$ kN، والركن 542.1 والتاج 237.2 kN·m قصاد المضبوط 59.0 و 354.0 و 487.9. وبأعمدة ثابتة 400 × 900 ($n = 1.942$) المجموعتين من المفصلات بيدّوا $X = 614.4/4.8 = 128.0$ kN، والركن 512.0، والقاعدة 256.0، والتاج 192.0 kN·m قصاد المضبوط 118.0 kN و 423.7 و 284.5 و 300.3 kN·m؛ وطريقة H/3 الأقرب بتدّي $X = 110.7$ kN، والركن 442.7، والتاج 295.9 — بس 221.4 kN·m بس عند القاعدة، لأن الأركان كمان بتفتح."}},{t:"p",text:{en:"**Why the fixed gable is where they are used most.** A gable on fixed bases moves sideways as its ridge drops, so a distribution would need sway corrections; and even with symmetry it keeps two redundants, so virtual work needs two equations, each with its own product integrals. That is too long for an exam: put both sets of hinges in and the frame is solved by statics alone. A straight frame (one balance) and a two-hinged gable (one redundant) are short enough to be solved properly.",ar:"**ليه الجمالوني الثابت هو أكتر مكان بنستخدمها فيه.** الجمالوني على ركائز ثابتة بيتحرك لجنب وتاجه بينزل، فالتوزيع هيحتاج تصحيحات للإزاحة الجانبية (Sway)؛ وحتى مع التماثل بيفضل فيه مجهولين زايدين، فالشغل الافتراضي محتاج معادلتين، كل واحدة بتكاملاتها. ده طويل على الامتحان: حط المجموعتين من المفصلات والإطار بيتحل بالاستاتيكا لوحدها. أما الإطار المستقيم (توازن واحد) والجمالوني ذو المفصلين (مجهول زائد واحد) فقصيرين كفاية إنهم يتحلوا صح."}},{t:"p",text:{en:"The L/5 hinges also give the **thrust** of a frame that carries other systems on its knees: with $M = 0$ at $L/5$, the moments of everything left of that point about it give the hinge thrust $H$ in one equation. Under its own uniform load alone it is $H = 0.08\\,wL^2/h$ — 900/5 = 180 kN for the checkpoint below with $h = 5$ m.",ar:"مفصلات L/5 بتدّي كمان **الدفع الأفقي** لإطار شايل أنظمة تانية على أركانه: بـ $M = 0$ عند $L/5$، عزوم كل اللي على شمال النقطة دي حواليها بتدّي دفع المفصلة $H$ في معادلة واحدة. وتحت حمله الموزع المنتظم بس بيطلع $H = 0.08\\,wL^2/h$ — يعني 900/5 = 180 kN للسؤال اللي تحت لو $h = 5$ م."}},{t:"note",tone:"tip",text:{en:"Use the approximate methods only for a first size, a sanity check, or when the time of an exam runs out. The one balance and the virtual-work solution are both short enough for an exam.",ar:"استخدم الحلول التقريبية بس لأول تكبير للقطاعات، أو لمراجعة سريعة، أو لما وقت الامتحان يخلص. والتوازن الواحد وحل الشغل الافتراضي الاتنين قصيرين كفاية للامتحان."}},{t:"quiz",q:{kind:"num",q:{en:"Hinges at L/5: w = 50 kN/m, L = 15 m. Knee moment (kN·m)?",ar:"مفصلات عند L/5: w = 50 kN/m، و L = 15 م. عزم الركن (kN·m)؟"},answer:900,tol:.003,unit:"kN·m",explain:{en:"$0.08\\times50\\times15^2 = 900$ kN·m: the middle 9 m hangs 225 kN on each 3 m cantilever, $225\\times3 + 50\\times3^2/2 = 900$.",ar:"$0.08\\times50\\times15^2 = 900$ kN·m: الـ 9 م اللي في النص بتعلّق 225 kN على كل كابولي 3 م، $225\\times3 + 50\\times3^2/2 = 900$."}}}]},{id:"shapes",title:{en:"Guessing the B.M.D: stiffness, determinacy and a push at the knee",ar:"تخمين منحنى العزوم: الجساءة والتحديد وزقة عند الركن"},blocks:[{t:"p",text:{en:"Before any number, the shape of the B.M.D of an indeterminate frame follows the ratio of its stiffnesses. For a two-hinged frame under a uniform load, write $k = (I_b/I_c)(h/L)$: the one balance then gives the knee moment in closed form.",ar:"قبل أي رقم، شكل منحنى العزوم في الإطار غير المحدد بيمشي مع النسبة بين جساءاته. لإطار ذو مفصلين تحت حمل موزع منتظم، اكتب $k = (I_b/I_c)(h/L)$: والتوازن الواحد بيدّي عزم الركن في معادلة مقفولة."}},{t:"eq",tex:["M_{knee} = \\dfrac{wL^2}{4\\,(2k + 3)},\\qquad M_{mid} = \\dfrac{wL^2}{8} - M_{knee},\\qquad k = \\dfrac{I_b}{I_c}\\cdot\\dfrac{h}{L}"],caption:{en:"Two-hinged frame, uniform load w on the beam — the same as DF_c·wL²/12 with K_c = ¾I_c/h and K_b = ½I_b/L.",ar:"إطار ذو مفصلين، حمل موزع منتظم w على الكمرة — نفس DF_c·wL²/12 بـ K_c = ¾I_c/h و K_b = ½I_b/L."}},{t:"table",head:[{en:"Stiffness",ar:"الجساءة"},{en:"Knee",ar:"الركن"},{en:"Mid-span",ar:"نص البحر"}],rows:[[{en:"deep beam, slender columns (k very large)",ar:"كمرة عميقة وأعمدة نحيفة (k كبيرة جداً)"},"≈ 0","$wL^2/8$"],[{en:"similar stiffness (k = 0.5)",ar:"جساءة متقاربة (k = 0.5)"},"$wL^2/16$","$wL^2/16$"],[{en:"very stiff columns (k very small)",ar:"أعمدة جاسئة جداً (k صغيرة جداً)"},"$wL^2/12$","$wL^2/24$"]],caption:{en:"Hogging at the knees, sagging at mid-span: the beam moves from a simple beam towards a fixed-ended one as the columns stiffen.",ar:"عزم سالب عند الأركان وموجب في النص: الكمرة بتتحول من كمرة بسيطة لكمرة ثابتة الطرفين كل ما الأعمدة تجسأ."}},{t:"p",text:{en:"**Example** ($L = 16$ m, $h = 6$ m, $w = 40$ kN/m, $wL^2/8 = 1280$ kN·m). $I_b = 10\\,I_c$: $k = 3.75$, knee $10240/42 = 243.8$ and mid-span 1036.2 kN·m — almost a simple beam. $I_b = 1.333\\,I_c$: $k = 0.5$, both 640 kN·m $= wL^2/16$. $I_b = 0.2\\,I_c$: $k = 0.075$, knee 812.7 and mid-span 467.3 kN·m, close to $wL^2/12 = 853.3$ and $wL^2/24 = 426.7$. Equal inertias with $h = L$ ($k = 1$) give $wL^2/20$ at the knee and $wL^2/13.3$ at mid-span. A central point load $F$ moves the same way, from the simple-beam $FL/4$ (slender columns) to the fixed-beam $\\pm FL/8$ (very stiff columns), with $M_{knee} = 3FL/(8(2k + 3))$ — 300 kN·m at the knees and 500 at mid-span for $F = 200$ kN at $k = 0.5$.",ar:"**مثال** ($L = 16$ م، و $h = 6$ م، و $w = 40$ kN/m، و $wL^2/8 = 1280$ kN·m). $I_b = 10\\,I_c$: $k = 3.75$، والركن $10240/42 = 243.8$ ونص البحر 1036.2 kN·m — تقريباً كمرة بسيطة. و $I_b = 1.333\\,I_c$: $k = 0.5$، والاتنين 640 kN·m $= wL^2/16$. و $I_b = 0.2\\,I_c$: $k = 0.075$، والركن 812.7 ونص البحر 467.3 kN·m، قريبين من $wL^2/12 = 853.3$ و $wL^2/24 = 426.7$. وعزوم القصور المتساوية مع $h = L$ ($k = 1$) بتدّي $wL^2/20$ عند الركن و $wL^2/13.3$ في النص. والحمل المركز $F$ في النص بيمشي بنفس الطريقة، من $FL/4$ بتاعة الكمرة البسيطة (أعمدة نحيفة) لـ $\\pm FL/8$ بتاعة الكمرة الثابتة (أعمدة جاسئة جداً)، و $M_{knee} = 3FL/(8(2k + 3))$ — 300 kN·m عند الأركان و 500 في النص لـ $F = 200$ kN عند $k = 0.5$."}},{t:"note",tone:"tip",text:{en:"In a determinate system — a frame on a hinge and a roller, a three-hinged frame — the stiffness of the members changes neither the value nor the shape of the B.M.D: under the same central load the hinge–roller frame gives FL/4 at mid-span whatever the depths.",ar:"في النظام المحدد — إطار على ركيزة مفصلية ومتحركة، أو إطار ثلاثي المفصلات — جساءة الأعضاء مابتغيّرش لا قيمة منحنى العزوم ولا شكله: تحت نفس الحمل المركز في النص الإطار المفصلي–المتحرك بيدّي FL/4 في النص مهما كانت الأعماق."}},{t:"p",text:{en:"**A push at one knee.** An untied arch slab or saw-tooth beside the hall, or the wind at the eaves, pushes one knee sideways by $F$, and the frame sways. Solve it by virtual work, or by superposition in three steps: (1) the vertical loads alone, by moment distribution (or approximately when time is short) → $X_1$ inwards at both hinges and $Y_1$; (2) the push alone → $F/2$ at each hinge, both against $F$, and $Y_2 = F\\,h/L$, down under the pushed knee and up under the other — knee moments $\\pm(F/2)\\,h$, the beam passing through zero at mid-span; (3) add the reactions first, then draw the B.M.D and the N.F.D.",ar:"**زقة عند ركن واحد.** بلاطة مقوّسة أو منشارية من غير شداد جنب الصالة، أو الرياح عند الأركان، بتزق ركن واحد لجنب بقوة $F$، والإطار بيحصله إزاحة جانبية (Sway). حلّه بالشغل الافتراضي، أو بالتجميع على تلات خطوات: (1) الأحمال الرأسية لوحدها، بتوزيع العزوم (أو تقريبي لو الوقت ضيق) ← $X_1$ لجوه عند المفصلتين و $Y_1$؛ (2) الزقة لوحدها ← $F/2$ عند كل مفصلة، الاتنين عكس $F$، و $Y_2 = F\\,h/L$، لتحت تحت الركن المزقوق ولفوق تحت التاني — وعزوم الأركان $\\pm(F/2)\\,h$، والكمرة بتعدّي بالصفر في النص؛ (3) اجمع ردود الأفعال الأول، وبعدين ارسم منحنى العزوم ومنحنى القوى العمودية."}},{t:"eq",tex:["H_{pushed} = X_1 - \\dfrac{F}{2},\\qquad H_{far} = X_1 + \\dfrac{F}{2},\\qquad Y_2 = \\dfrac{F\\,h}{L}"],caption:{en:"Hinge thrusts after superposition (inwards positive); Y₂ is taken off the pushed side and added to the far side.",ar:"دفع المفصلات بعد التجميع (لجوه موجب)؛ و Y₂ بتتطرح من ناحية الزقة وتتزوّد على الناحية التانية."}},{t:"p",text:{en:"**Example — the 20 m hall** ($X_1 = 169.5$ kN, knee 1271.4 kN·m, $h = 7.5$ m, $Y = 906.6$ kN) pushed by $F = 120$ kN at its left knee: 60 kN at each hinge and $Y_2 = 120\\times7.5/20 = 45$ kN. Left hinge $169.5 - 60 = 109.5$ kN inwards, right hinge 229.5 kN; knees $1271.4 - 450 = 821.4$ and $1271.4 + 450 = 1721.4$ kN·m; vertical reactions 861.6 and 951.6 kN. Usually $X_1 > F/2$ and both knees still hog. If $X_1 < F/2$ — here $F = 450$ kN — the left hinge thrust turns outwards (55.5 kN) and the left knee reverses ($1271.4 - 1687.5 = -416.1$ kN·m): the main bars of that column move to its **inner** face and run into the bottom of the beam, with nominal bars on the outer face.",ar:"**مثال — صالة الـ 20 م** ($X_1 = 169.5$ kN، والركن 1271.4 kN·m، و $h = 7.5$ م، و $Y = 906.6$ kN) مزقوقة بـ $F = 120$ kN عند ركنها الشمال: 60 kN عند كل مفصلة و $Y_2 = 120\\times7.5/20 = 45$ kN. المفصلة الشمال $169.5 - 60 = 109.5$ kN لجوه، واليمين 229.5 kN؛ والأركان $1271.4 - 450 = 821.4$ و $1271.4 + 450 = 1721.4$ kN·m؛ وردود الأفعال الرأسية 861.6 و 951.6 kN. عادة $X_1 > F/2$ والركنين لسه بعزم سالب. ولو $X_1 < F/2$ — هنا $F = 450$ kN — دفع المفصلة الشمال بيقلب لبره (55.5 kN) والركن الشمال بيعكس ($1271.4 - 1687.5 = -416.1$ kN·m): الحديد الرئيسي في العمود ده بينتقل لوشه **الداخلي** وبيدخل في بطن الكمرة، وعلى الوش الخارجي أسياخ إنشائية."}},{t:"quiz",q:{kind:"num",q:{en:"Two-hinged frame with k = 0.5, w = 30 kN/m, L = 16 m. Knee moment (kN·m)?",ar:"إطار ذو مفصلين بـ k = 0.5، و w = 30 kN/m، و L = 16 م. عزم الركن (kN·m)؟"},answer:480,tol:.005,unit:"kN·m",explain:{en:"$30\\times16^2/(4\\times(1 + 3)) = 7680/16 = 480$ kN·m $= wL^2/16$, the same as at mid-span.",ar:"$30\\times16^2/(4\\times(1 + 3)) = 7680/16 = 480$ kN·m $= wL^2/16$، زي نص البحر بالظبط."}}}]},{id:"thrust",title:{en:"The thrust line",ar:"خط الضغط"},blocks:[{t:"p",text:{en:"Every section of an arch or a frame carries a normal force $P$ and a moment $M$ — together, $P$ acting at the eccentricity $e = M/P$ from the axis. The line through these points is the **thrust (pressure) line**. Shape the member along it and $e = 0$: the section is in pure compression and can be thin. That shape is the inverted B.M.D of the loads on the imaginary simple beam — a parabola under a uniform load, a polygon under point loads.",ar:"كل قطاع في عقد أو إطار شايل قوة عمودية $P$ وعزم $M$ — وده مع بعض معناه $P$ مؤثرة بلامركزية $e = M/P$ من المحور. الخط اللي بيعدّي على النقط دي هو **خط الضغط**. شكّل العنصر عليه يبقى $e = 0$: القطاع ضغط صافي ويقدر يبقى رفيع. والشكل ده هو منحنى عزوم الأحمال على الكمرة البسيطة التخيلية مقلوب — قطع مكافئ تحت حمل موزع منتظم، ومضلع تحت أحمال مركزة."}},{t:"eq",tex:["e = \\dfrac{M}{P}","y(x) = \\dfrac{4h\\,x\\,(L - x)}{L^2}"],caption:{en:"The funicular of a uniform load: a parabola of rise h.",ar:"الشكل الحبلي للحمل الموزع المنتظم: قطع مكافئ ارتفاعه h."}},{t:"p",text:{en:"**Arch slab** — a three-hinged parabolic shell strip, 1 m wide. Under the full load $M \\approx 0$ and the springing takes $Y$, $X$ and their resultant $P$. Example: $L = 15$ m, $h = 3$ m, $w = 6.5$ kN/m²: $Y = 6.5\\times15/2 = 48.75$, $X = 6.5\\times15^2/(8\\times3) = 60.94$ and $P = \\sqrt{60.94^2 + 48.75^2} = 78.04$ kN per metre. A load on one half only is no longer funicular, and the same arch bends.",ar:"**بلاطة مقوّسة** — شريحة قشرية على شكل قطع مكافئ بتلات مفصلات، عرضها 1 م. تحت الحمل الكامل $M \\approx 0$ والارتكاز بياخد $Y$ و $X$ ومحصلتهم $P$. مثال: $L = 15$ م، و $h = 3$ م، و $w = 6.5$ kN/m²: $Y = 6.5\\times15/2 = 48.75$، و $X = 6.5\\times15^2/(8\\times3) = 60.94$ و $P = \\sqrt{60.94^2 + 48.75^2} = 78.04$ kN لكل متر. ولو الحمل على نص واحد بس مبقاش حبلي، ونفس العقد بينحني."}},{t:"eq",tex:"Y = \\dfrac{wL}{2},\\qquad X = \\dfrac{wL^2}{8h},\\qquad P = \\sqrt{X^2 + Y^2}"},{t:"quiz",q:{kind:"num",q:{en:"Arch slab: w = 8 kN/m², L = 12 m, rise 2.4 m. Thrust X (kN/m)?",ar:"بلاطة مقوّسة: w = 8 kN/m²، و L = 12 م، والارتفاع 2.4 م. الدفع الأفقي X (kN/m)؟"},answer:60,tol:.003,unit:"kN/m",explain:{en:"$8\\times12^2/(8\\times2.4) = 60$ kN per metre.",ar:"$8\\times12^2/(8\\times2.4) = 60$ kN لكل متر."}}}]},{id:"polygon",title:{en:"Tied polygon frames and arch girders",ar:"الإطارات المضلعة والكمرات المقوّسة بشداد"},blocks:[{t:"p",text:{en:"A polygon frame follows the funicular of its joint loads with straight members: a triangle for one load, a trapezoid for two; with more sides it becomes an **arch girder**, its joints at $h_i = (M_i/M_{max})\\,h$ of the imaginary beam. A tie between the supports takes the thrust, so the columns below get only vertical loads. Approximately:",ar:"الإطار المضلع بيمشي على الشكل الحبلي لأحمال عقده بأعضاء مستقيمة: مثلث لحمل واحد، وشبه منحرف لحملين؛ ولو الأضلاع كترت يبقى **كمرة مقوّسة**، عقدها على ارتفاعات $h_i = (M_i/M_{max})\\,h$ من عزوم الكمرة البسيطة التخيلية. والشداد بين الركائز بياخد الدفع الأفقي، فالأعمدة اللي تحت بتاخد أحمال رأسية بس. تقريباً:"}},{t:"eq",tex:["T = P = \\dfrac{M_0}{h}","M = 0.05\\,M_0,\\qquad T = P = 0.95\\,\\dfrac{M_0}{h}"],caption:{en:"M₀ = the largest moment of the imaginary simple beam under the joint loads; h = the rise. Second line: allowing for the elongation of the tie.",ar:"M₀ = أكبر عزم على الكمرة البسيطة التخيلية تحت أحمال العقد؛ و h = الارتفاع. السطر التاني: بحساب استطالة الشداد."}},{t:"p",text:{en:"Why 5%? A tie designed exactly for $T$ works at $f_y/\\gamma_s$ and stretches $\\Delta = L\\,(f_y/\\gamma_s)/E_s$ — 31 mm for an 18 m tie of B400 steel. The frame spreads by that much and takes part of the thrust back as bending; more tie steel means less stress, less stretch, less moment. You will also meet the stretch written as $(1/E_c)(L/n)(F_y/\\gamma_s)$ with $n = 15$ — the same formula with $E_s = 15E_c \\approx 330000$ N/mm². Use the real $E_s = 200000$ N/mm²: it gives the larger, safer stretch.",ar:"ليه 5%؟ الشداد المصمم على $T$ بالظبط بيشتغل عند $f_y/\\gamma_s$ وبيستطيل $\\Delta = L\\,(f_y/\\gamma_s)/E_s$ — 31 مم لشداد 18 م من حديد B400. الإطار بيفتح بالقدر ده وبيرجّع جزء من الدفع عزوم؛ وكل ما حديد الشداد يزيد الإجهاد يقل والاستطالة تقل والعزم يقل. وهتلاقي الاستطالة مكتوبة كمان $(1/E_c)(L/n)(F_y/\\gamma_s)$ بـ $n = 15$ — نفس المعادلة بـ $E_s = 15E_c \\approx 330000$ N/mm². استخدم $E_s = 200000$ N/mm² الحقيقية: بتدّي استطالة أكبر وفي الأمان."}},{t:"p",text:{en:"**Examples.** A trapezoidal frame, $L = 18$ m in three 6 m panels, $h = 2.5$ m, 250 kN at each top joint: $M_0 = 250\\times6 = 1500$ kN·m, $T = 600$ kN in theory, 570 kN with $M = 75$ kN·m by the rule. An arch girder of 24 m in six 4 m panels, $h = 3.2$ m, 200 kN at every joint: $M_0 = 500\\times12 - 200\\times(8 + 4) = 3600$ kN·m → $T = 0.95\\times3600/3.2 = 1068.75$ kN, $M = 180$ kN·m; its joints stand at 1.78, 2.84 and 3.20 m. In the lab the rigid tie of the trapezoid carries 592.3 kN; a stretching tie with twice the minimum steel leaves 10.8% of $M_0$ in the frame — the 5% benchmark needs about five times the minimum steel here.",ar:"**أمثلة.** إطار شبه منحرف، $L = 18$ م على تلات بواكي 6 م، و $h = 2.5$ م، و 250 kN على كل عقدة علوية: $M_0 = 250\\times6 = 1500$ kN·m، و $T = 600$ kN نظرياً، و 570 kN مع $M = 75$ kN·m بالقاعدة. وكمرة مقوّسة 24 م على ست بواكي 4 م، و $h = 3.2$ م، و 200 kN على كل عقدة: $M_0 = 500\\times12 - 200\\times(8 + 4) = 3600$ kN·m ← $T = 0.95\\times3600/3.2 = 1068.75$ kN، و $M = 180$ kN·m؛ وعقدها على ارتفاعات 1.78 و 2.84 و 3.20 م. في المعمل الشداد الجاسئ بتاع شبه المنحرف بيشيل 592.3 kN؛ والشداد اللي بيستطيل بضعف الحديد الأدنى بيسيب 10.8% من $M_0$ في الإطار — وحد الـ 5% محتاج حوالي خمس أضعاف الحديد الأدنى هنا."}},{t:"lab",lab:"frame",height:480,props:{template:"polygon",lockTemplate:!0,defaultTab:"hand",missions:_},caption:{en:"A tied trapezoidal frame. Switch the tie between rigid and stretching, raise its steel k, add sides until it becomes an arch girder, and load half of it.",ar:"إطار شبه منحرف بشداد. بدّل الشداد بين جاسئ وبيستطيل، وزوّد حديده k، وزوّد الأضلاع لحد ما يبقى كمرة مقوّسة، وحمّل نصه."}},{t:"quiz",q:{kind:"num",q:{en:"Polygon frame: M₀ = 2000 kN·m, rise 2.5 m. Tie force by the approximate rule (kN)?",ar:"إطار مضلع: M₀ = 2000 kN·m، والارتفاع 2.5 م. قوة الشداد بالقاعدة التقريبية (kN)؟"},answer:760,tol:.003,unit:"kN",explain:{en:"$0.95\\times2000/2.5 = 760$ kN (and $M = 0.05\\times2000 = 100$ kN·m).",ar:"$0.95\\times2000/2.5 = 760$ kN (و $M = 0.05\\times2000 = 100$ kN·m)."}}}]},{id:"apply",title:{en:"Your building: the workshop as an RC hall frame",ar:"مبناك: الورشة كإطار صالة خرساني"},blocks:[{t:"p",text:{en:"The steel workshop spans 12 m with trusses every 6 m. Re-imagine it in RC: four two-hinged frames across the span at $S = 6$ m, a 120 mm roof slab on 250 × 500 secondary beams every 2 m, frame beams 300 × 1000 ($L/12$) and columns 300 × 800 at the knee tapered to 400 at the hinges, $h = 6.0$ m. Loads (ultimate): $w_s = 1.4\\times(3.0 + 3.0) + 1.6\\times1.0 = 10.0$ kN/m²; five secondary beams on the span, each $P = (10.0\\times2 + 3.325)\\times6 = 139.95$ kN, and over each knee an edge beam of $(10.0\\times1 + 3.325)\\times6 = 79.95$ kN that goes straight into the column; beam own weight 9.24 kN/m → $w = 9.24 + 5\\times139.95/12 = 67.55$ kN/m.",ar:"الورشة المعدنية بحرها 12 م وجمالوناتها كل 6 م. تخيّلها خرسانة: أربع إطارات ذات مفصلين على البحر كل $S = 6$ م، وبلاطة سقف 120 مم على كمرات متشالة 250 × 500 كل 2 م، وكمرات إطار 300 × 1000 ($L/12$) وأعمدة 300 × 800 عند الركن متدرّجة لـ 400 عند المفصلات، و $h = 6.0$ م. الأحمال (أقصى): $w_s = 1.4\\times(3.0 + 3.0) + 1.6\\times1.0 = 10.0$ kN/m²؛ وخمس كمرات متشالة على البحر، كل واحدة $P = (10.0\\times2 + 3.325)\\times6 = 139.95$ kN، وفوق كل ركن كمرة طرفية $(10.0\\times1 + 3.325)\\times6 = 79.95$ kN بتنزل في العمود على طول؛ ووزن الكمرة 9.24 kN/m ← $w = 9.24 + 5\\times139.95/12 = 67.55$ kN/m."}},{t:"p",text:{en:"Inertias: $B = 6\\times0.12 + 0.30 = 1.02$ m, $\\alpha = 0.12$, $\\beta = 0.294$ → $\\mu = 373$ → $I_b = 0.0381$ m⁴; $I_c = 0.3\\times(\\tfrac56\\times0.8)^3/12 = 0.00741$ m⁴ → $I_b = 5.142\\,I_c$. $K_c = 0.75/6 = 0.125\\,I_c$, $K_b = 0.5\\times5.142/12 = 0.2143\\,I_c$ → $DF_c = 0.368$. $M_{fe} = 67.55\\times12^2/12 = 810.6$ kN·m → **$M_F = 298.7$ kN·m, $X = 49.8$ kN**, $Y = 67.55\\times6 + 79.95 = 485.3$ kN, mid-span $1215.9 - 298.7 = 917.3$ kN·m. With fixed bases the columns are prismatic and as deep as the beam, 300 × 1000 ($3.375\\,I_c$): $DF_c = 0.724$, $M_F = 587.0$, $M_{base} = 293.5$ kN·m, $X = 146.8$ kN, mid-span 628.9 kN·m. The two-hinged frame keeps its footings free of moment; to centre the soil pressure under the thrust its footing is shifted outwards by $e = X(t_1 + t_2)/Y = 49.8\\times1.0/523.1 = 0.095$ m ($Y$ with the 37.8 kN of the column). Click a footing of the building.",ar:"عزوم القصور: $B = 6\\times0.12 + 0.30 = 1.02$ م، و $\\alpha = 0.12$، و $\\beta = 0.294$ ← $\\mu = 373$ ← $I_b = 0.0381$ م⁴؛ و $I_c = 0.3\\times(\\tfrac56\\times0.8)^3/12 = 0.00741$ م⁴ ← $I_b = 5.142\\,I_c$. و $K_c = 0.75/6 = 0.125\\,I_c$، و $K_b = 0.5\\times5.142/12 = 0.2143\\,I_c$ ← $DF_c = 0.368$. و $M_{fe} = 67.55\\times12^2/12 = 810.6$ kN·m ← **$M_F = 298.7$ kN·m، و $X = 49.8$ kN**، و $Y = 67.55\\times6 + 79.95 = 485.3$ kN، ونص البحر $1215.9 - 298.7 = 917.3$ kN·m. وبركائز ثابتة الأعمدة منشورية وبعمق الكمرة، 300 × 1000 ($3.375\\,I_c$): $DF_c = 0.724$، و $M_F = 587.0$، و $M_{base} = 293.5$ kN·m، و $X = 146.8$ kN، ونص البحر 628.9 kN·m. الإطار ذو المفصلين بيسيب قواعده من غير عزم؛ وعلشان ضغط التربة يتوسّط تحت الدفع قاعدته بتترحّل لبره بمسافة $e = X(t_1 + t_2)/Y = 49.8\\times1.0/523.1 = 0.095$ م ($Y$ مع الـ 37.8 kN بتوع العمود). اضغط على قاعدة من قواعد المبنى."}},{t:"widget",w:"building",props:{focus:"F-B4",tags:["footings","cols-g","beams-1","slab-1","cols-1","beams-2","slab-2","ws-columns","ws-trusses","sys-indet"]}},{t:"quiz",q:{kind:"num",q:{en:"The RC workshop frame, two-hinged: horizontal reaction X (kN)?",ar:"إطار الورشة الخرساني بمفصلين: رد الفعل الأفقي X (kN)؟"},answer:49.78,tol:.005,unit:"kN",explain:{en:"$M_F = 810.6\\times0.368 = 298.7$ kN·m; $X = 298.7/6 = 49.8$ kN.",ar:"$M_F = 810.6\\times0.368 = 298.7$ kN·m؛ و $X = 298.7/6 = 49.8$ kN."}}}]}],quiz:[{kind:"num",q:{en:"A 110 mm solid slab on a 350 mm wide beam. Flange width B (m)?",ar:"بلاطة مصمتة 110 مم على كمرة عرضها 350 مم. عرض الشفة B (م)؟"},answer:1.01,tol:.003,unit:"m",explain:{en:"$B = 6\\times0.11 + 0.35 = 1.01$ m.",ar:"$B = 6\\times0.11 + 0.35 = 1.01$ م."}},{kind:"num",q:{en:"Fixed-base frame: L = 16 m, h = 5 m, I_b = 2 I_c. D.F. of the column?",ar:"إطار ثابت الركائز: L = 16 م، و h = 5 م، و I_b = 2 I_c. معامل توزيع العمود؟"},answer:.7619,tol:.003,explain:{en:"$K_c = 1/5 = 0.2$, $K_b = 0.5\\times2/16 = 0.0625$ → $0.2/0.2625 = 0.762$.",ar:"$K_c = 1/5 = 0.2$، و $K_b = 0.5\\times2/16 = 0.0625$ ← $0.2/0.2625 = 0.762$."}},{kind:"num",q:{en:"Two-hinged frame: F.E.M. = 1500 kN·m, DF_c = 0.6, h = 6 m. Horizontal reaction X (kN)?",ar:"إطار ذو مفصلين: F.E.M = 1500 kN·m، و DF_c = 0.6، و h = 6 م. رد الفعل الأفقي X (kN)؟"},answer:150,tol:.003,unit:"kN",explain:{en:"$M_F = 1500\\times0.6 = 900$; $X = 900/6 = 150$ kN.",ar:"$M_F = 1500\\times0.6 = 900$؛ و $X = 900/6 = 150$ kN."}},{kind:"mcq",q:{en:"The 5/6·t depth is used for…",ar:"العمق 5/6·t بيستخدم لـ…"},options:[{en:"the tapered column of a two-hinged frame",ar:"العمود المتدرّج في الإطار ذو المفصلين"},{en:"the column of a fixed-base frame",ar:"عمود الإطار ثابت الركائز"},{en:"the beam in a sky-light zone",ar:"الكمرة في منطقة الشخشيخة"}],answer:0,explain:{en:"It replaces the taper t/2 → t by an equivalent prism; a fixed column keeps b·t³/12.",ar:"بيبدّل التدريج t/2 ← t بمنشور مكافئ؛ والعمود الثابت بياخد b·t³/12."}},{kind:"tf",q:{en:"For a symmetric frame under a symmetric load, one balance at the knee gives the exact knee moment.",ar:"لإطار متماثل تحت حمل متماثل، توازن واحد عند الركن بيدّي عزم الركن المضبوط."},answer:!0,explain:{en:"The far ends are already accounted for in K = ½I/L and ¾I/h (or I/h); nothing is left to carry over and back.",ar:"الأطراف البعيدة محسوبة أصلاً في K = ½I/L و ¾I/h (أو I/h)؛ مفيش حاجة تتنقل وترجع تاني."}},{kind:"num",q:{en:"EI_c·δ₁₀ = −12000, EI_c·δ₁₁ = 400. The redundant X (kN)?",ar:"EI_c·δ₁₀ = −12000، و EI_c·δ₁₁ = 400. المجهول الزائد X (kN)؟"},answer:30,tol:.003,unit:"kN",explain:{en:"$X = -\\delta_{10}/\\delta_{11} = 12000/400 = 30$ kN.",ar:"$X = -\\delta_{10}/\\delta_{11} = 12000/400 = 30$ kN."}},{kind:"num",q:{en:"Arch girder: M₀ = 3000 kN·m, rise 3.0 m. Tie force by the approximate rule (kN)?",ar:"كمرة مقوّسة: M₀ = 3000 kN·m، والارتفاع 3.0 م. قوة الشداد بالقاعدة التقريبية (kN)؟"},answer:950,tol:.003,unit:"kN",explain:{en:"$0.95\\times3000/3 = 950$ kN.",ar:"$0.95\\times3000/3 = 950$ kN."}},{kind:"mcq",q:{en:"The tie of a polygon frame stretches more — and leaves more bending in the frame — when…",ar:"شداد الإطار المضلع بيستطيل أكتر — وبيسيب عزوم أكتر في الإطار — لما…"},options:[{en:"it has just the steel its force needs (it works at f_y/γ_s)",ar:"يكون فيه الحديد اللي قوته محتاجاه بالظبط (بيشتغل عند f_y/γ_s)"},{en:"it has twice that steel",ar:"يكون فيه ضعف الحديد ده"},{en:"the rise is larger",ar:"الارتفاع يكون أكبر"}],answer:0,explain:{en:"Δ = L·σ/E_s: the fully stressed tie stretches the most; extra steel lowers σ and the stretch.",ar:"Δ = L·σ/E_s: الشداد المجهَد بالكامل بيستطيل أكتر؛ والحديد الزيادة بيقلل σ والاستطالة."}}]};export{b as default};
